export function bible_glyph_chapters_tagalog() {
  "Every picture Bible chapter in plain Tagalog, one entry a chapter, for the band a Tagalog reader checks themselves against after they have guessed.";
  "THIS FILE IS WRITTEN BY A COMMAND AND NOT BY HAND. It is a public-domain bible read once, at authoring time, for the chapters the pictures have reached.";
  "IT IS COMMITTED RATHER THAN FETCHED because this Bible is meant to reach a phone with no network, and a reveal that needed one would fail in exactly the situation the pictures were chosen for.";
  "IT IS NOT A LINE OF PICTURES AND CANNOT BECOME ONE. A picture verse is marks interleaved into English word order, so a line of pictures in this language would have to be authored a chapter at a time exactly as the English ones were.";
  let chapters = [{"chapter_code":"1JN04","verses":[{"verse_number":1,"text":"Minamahal, huwag maniwala sa bawat espiritu, pero suriin ang mga espiritu upang makita kung sila ay sa Diyos, dahil maraming mga bulaang propeta ang nagsilabasan sa mundo."},{"verse_number":2,"text":"Sa paraang ito malalaman mo ang Espiritu ng Diyos — ang bawat espiritu na kinikilala si Jesu-Cristo na nagkatawang tao ay sa Diyos,"},{"verse_number":3,"text":"at bawat espiritu na hindi kinikilala si Jesus ay hindi sa Diyos. Ito ang espiritu ng antikristo, na inyong narinig na darating, at ngayon ay nasa mundo na."},{"verse_number":4,"text":"Kayo ay sa Diyos, minamahal kong mga anak, at napagtagumpayan sila dahil ang siyang sumasainyo ay mas dakila kaysa siyang nasa mundo."},{"verse_number":5,"text":"Sila ay makamundo, kaya't ang sinasabi nila ay para sa mundo, at ang mundo ay nakikinig sa kanila."},{"verse_number":6,"text":"Tayo ay sa Diyos. Siyang nakakakilala sa Diyos ay nakikinig sa atin. Siyang hindi nasa Diyos ay hindi nakikinig sa atin. Sa pamamagitan nito nalalaman natin ang espiritu ng katotohan at ang espiritu ng kamalian."},{"verse_number":7,"text":"Minamahal, mahalin natin ang isa't isa, dahil ang pag-ibig ay sa Diyos, at lahat ng nagmamahal ay pinanganak sa Diyos at kilala ang Diyos."},{"verse_number":8,"text":"Ang taong hindi nagmamahal ay hindi kilala ang Diyos, dahil ang Diyos ay pag-ibig."},{"verse_number":9,"text":"Sa pamamagitan nito ang pag-ibig ng Diyos ay nahayag sa atin, na pinadala ng Diyos ang kanyang bugtong na anak sa mundo upang tayo ay maaring mabuhay sa pamamagitan niya."},{"verse_number":10,"text":"Sa ganito ang pag-ibig, hindi dahil minahal natin siya, kundi minahal niya tayo, at pinadala niya ang kanyang Anak na maging kabayaran ng ating mga kasalanan."},{"verse_number":11,"text":"Minamahal, kung tayo'y lubos na minahal ng Diyos, nararapat din nating mahalin ang bawat isa."},{"verse_number":12,"text":"Walang sinuman ang nakakita kailanman sa Diyos. Kung mahal natin ang isa't isa, ang Diyos ay mananatili sa atin at ang pag-ibig niya ay lubos na nasa atin."},{"verse_number":13,"text":"Sa pamamagitan nito malalaman natin na tayo ay nananatili sa kanya at siya sa atin, dahil binigay niya sa atin ang kanyang Espiritu."},{"verse_number":14,"text":"At nakita natin at nasaksihan na ipinadala ng Ama ang kanyang anak upang maging tagapagligtas ng mundo."},{"verse_number":15,"text":"Sinuman ang kumikilala na si Jesu-Cristo ay ang Anak ng Diyos, ang Diyos ay nananatili sa kanya at siya sa Diyos."},{"verse_number":16,"text":"At alam natin at pinaniwalaan ang pag-ibig na mayroon ang Diyos na nasa sa atin. Ang Diyos ay pag-ibig, at siyang nananatili sa pag-ibig ay nananatili sa Diyos, at ang Diyos ay nananatili sa kanya."},{"verse_number":17,"text":"Sa ganito ang pagmamahal ay ginawang lubos sa atin, nang sa gayon tayo ay maaring magkaroon ng kasiguraduhan sa araw ng paghuhukom, dahil gaya niya, gayon din tayo sa mundong ito."},{"verse_number":18,"text":"Walang anumang takot sa pag-ibig. Pero ang pag-ibig na lubos ay inaalis ang takot, dahil ang takot ay may kinalaman sa kaparusahan. Pero kung sinuman ang siyang natatakot ay hindi nagawang lubos sa pag-ibig."},{"verse_number":19,"text":"Nagmamahal tayo dahil minahal muna tayo ng Diyos."},{"verse_number":20,"text":"Kung sinuman ang nagsasabi, “Mahal ko ang Diyos” pero kinapopootan ang kanyang kapatid siya ay isang sinungaling. Pagkat ang sinuman na hindi umiibig sa kanyang kapatid, na kanyang nakikita, ay hindi umiibig sa Diyos, na hindi niya nakikita."},{"verse_number":21,"text":"At ito ang kautusan na mayroon tayo mula sa kanya: Kung sinuman ang nagmamahal sa Diyos ay dapat ding mahalin ang kanyang kapatid."}]},{"chapter_code":"JHN01","verses":[{"verse_number":1,"text":"Sa simula pa lamang ay ang Salita, at ang Salita ay kasama ng Diyos, at ang Salita ay Diyos."},{"verse_number":2,"text":"Itong Salitang ito ay nasa simula pa kasama ng Diyos."},{"verse_number":3,"text":"Ang lahat nang mga bagay ay nalikha sa pamamagitan niya, at kung wala siya, ay wala kahit isang bagay ang nilikha na nalikha."},{"verse_number":4,"text":"Sa kaniya ay buhay, at ang buhay na iyon ay liwanag sa lahat ng sangkatauhan."},{"verse_number":5,"text":"Ang liwanag ay sumisinag sa kadiliman, at ito ay hindi napawi nang kadiliman."},{"verse_number":6,"text":"May isang lalaki na isinugo mula sa Diyos, na ang pangalan ay Juan."},{"verse_number":7,"text":"Dumating siya bilang isang saksi upang magpatotoo tungkol sa liwanag, upang ang lahat ay maaaring maniwala sa pamamagitan niya."},{"verse_number":8,"text":"Hindi si Juan ang liwanag, ngunit naparito upang makapagpatotoo siya tungkol sa liwanag."},{"verse_number":9,"text":"Iyon ang tunay na liwanag na dumarating sa mundo at iyon ang nagpapaliwanang sa lahat."},{"verse_number":10,"text":"Siya ay nasa mundo, at ang mundo ay nalikha sa pamamagitan niya, at ang mundo ay hindi nakakakilala sa kaniya."},{"verse_number":11,"text":"Dumating siya sa kaniyang sariling kababayan, at hindi siya tinanggap ng kaniyang sariling mga kababayan."},{"verse_number":12,"text":"Ngunit sa kasing-dami nang tumanggap sa kaniya, na naniwala sa kaniyang pangalan, sa kanila niya ipinagkaloob ang karapatang maging mga anak ng Diyos,"},{"verse_number":13,"text":"ipinanganak sila hindi sa pamamagitan nang dugo, ni hindi sa pamamagitan nang kagustuhan ng laman, ni hindi sa pamamagitan nang kagustuhan ng tao, kundi sa pamamagitan ng Diyos."},{"verse_number":14,"text":"Ngayon ang Salita ay naging laman at namuhay na kasama namin. Nakita namin ang kaniyang kaluwalhatian,  kaluwalhatiang katulad ng nasa nag-iisang natatanging katauhan na naparito mula sa Ama, punong-puno ng biyaya at katotohanan."},{"verse_number":15,"text":"Pinatotohanan ni Juan ang tungkol sa kaniya at sumigaw na nagsasabi, “Siyang sinabi ko sa inyo, 'Ang darating kasunod ko ay mas higit sa akin, sapagkat siya ay nauna sa akin.'”"},{"verse_number":16,"text":"Sapagkat mula sa kaniyang kapuspusan tayong lahat ay nakatanggap ng sunod-sunod na libreng kaloob."},{"verse_number":17,"text":"Sapagkat ang kautusan ay ibinigay sa pamamagitan ni Moises. Biyaya at katotohanan ay dumating sa pamamagitan ni Jesu-Cristo."},{"verse_number":18,"text":"Kailanman, walang tao ang nakakita sa Diyos. Ang isa at nag-iisang katauhan, na mismo ay Diyos, na siyang nasa dibdib ng Ama, nagawa niya siyang maipakilala."},{"verse_number":19,"text":"Ngayon ito ang patotoo ni Juan nang ang mga Judio ay nagpadala sa kaniya ng mga pari at mga Levita mula sa Jerusalem para tanungin siyang, “Sino ka?”"},{"verse_number":20,"text":"Malaya niyang inilahad, at hindi ikinaila, ngunit tumugon, “Hindi ako ang Cristo.”"},{"verse_number":21,"text":"Kaya siya ay tinanong nila, “Ano ka kung gayon? Ikaw ba si Elias?” Sabi niya, “Hindi ako.” Sabi nila, “Ikaw ba ang propeta?” Sumagot siya, “Hindi.”"},{"verse_number":22,"text":"Pagkatapos ay sinabi nila sa kaniya, “Sino ka, upang may maibigay kaming sagot sa mga nagsugo sa amin? Ano ang masasabi mo tungkol sa iyong sarili?”"},{"verse_number":23,"text":"Sinabi niya, “Ako ang boses ng isang sumisigaw sa ilang: 'Gawin ninyong tuwid ang daraanan ng Panginoon,' gaya nang sinabi ni Isaias na propeta.”"},{"verse_number":24,"text":"Ngayong mayroong mga isinugo duon mula sa mga Pariseo. Tinanong nila siya at sinabi sa kaniya,"},{"verse_number":25,"text":"“Kung ganoon bakit ka nagbabautismo kung hindi ikaw ang Cristo, ni hindi si Elias, ni hindi ang propeta?”"},{"verse_number":26,"text":"Tumugon si Juan sa kanila sinasabi, “Nagbabautismo ako ng tubig. Subalit, sa kalagitnaan ninyo ay nakatayo ang isang hindi ninyo nakikilala."},{"verse_number":27,"text":"Siya ang darating kasunod ko. Hindi ako karapat-dapat na magtanggal ng tali ng kaniyang sandalyas.”"},{"verse_number":28,"text":"Ang mga bagay na ito ay nangyari sa Bethania sa kabilang ibayo nang Jordan, kung saan si Juan ay nagbabautismo."},{"verse_number":29,"text":"Sa sumunod na araw nakita ni Juan na paparating si Jesus sa kaniya at sinabi, “Tingnan ninyo, ayun ang kordero ng Diyos na siyang nag-aalis nang mga kasalanan ng mundo!"},{"verse_number":30,"text":"Siya ang sinabi ko sa inyo na, 'Ang darating kasunod ko ay mas higit sa akin, sapagkat siya ay nauna sa akin.'"},{"verse_number":31,"text":"Hindi ko siya nakilala, ngunit ito ay nangyari upang maihayag siya sa Israel na siyang dahilan na ako ay nagbabautismo ng tubig.”"},{"verse_number":32,"text":"Nagpatotoo si Juan, “Nakita ko ang Espiritu na bumababa mula sa langit tulad ng isang kalapati, at ito ay nanatili sa kaniya."},{"verse_number":33,"text":"Hindi ko siya nakilala, ngunit ang sabi sa akin ng nagsugo sa akin na magbautismo sa tubig, 'Kung kanino mo makikita ang Espiritu na bumababa at nananatili, siya ang magbabautismo ng Banal na Espiritu.'"},{"verse_number":34,"text":"Pareho kong nakita at napatotohanan na ito ang Anak ng Diyos."},{"verse_number":35,"text":"Muli, sa sumunod na araw, habang si Juan ay nakatayong kasama ang dalawang alagad"},{"verse_number":36,"text":"nakita nila si Jesus na naglalakad sa malapit, at sinabi ni Juan, “Tingnan ninyo, ayun ang Kordero ng Diyos!”"},{"verse_number":37,"text":"Narinig ng dalawang alagad na sinabi ni Juan ito, at sila ay sumunod kay Jesus."},{"verse_number":38,"text":"At si Jesus ay lumingon at nakita silang sumusunod at sinabi sa kanila, “Anung nais ninyo?” Sumagot sila, “Rabi (na ang ibig sabihin ay 'Guro'), saan ka nakatira?”"},{"verse_number":39,"text":"Sinabi niya sa kanila, “Halikayo at tingnan.” At sila ay pumaroon at nakita kung saan siya nakatira; sila ay tumira kasama niya sa araw na iyon sapagkat noon ay halos mag-aalas kuwatro na."},{"verse_number":40,"text":"Isa sa dalawang nakarinig na nagsalita si Juan at pagkatapos sumunod kay Jesus ay si Andres na kapatid ni Simon Pedro."},{"verse_number":41,"text":"Una niyang nakita ang kaniyang sariling kapatid na si Simon at sinabi sa kaniya, “Nakita na namin ang Mesias,” (na sinalin na, 'ang Cristo')."},{"verse_number":42,"text":"Dinala niya siya kay Jesus. Si Jesus ay tumingin sa kaniya at sinabi, “Ikaw si Simon anak ni Juan. Ikaw ay tatawaging Cepas” (na ang ibig sabihin ay 'Pedro')."},{"verse_number":43,"text":"Kinabukasan, nang si Jesus ay nais na umalis para pumunta sa Galilea, nakita niya si Felipe at sinabi sa kaniya, “Sumunod ka sa akin.”"},{"verse_number":44,"text":"Ngayon si Felipe ay galing sa Bethsaida, ang lungsod nila Andres at Pedro."},{"verse_number":45,"text":"Natagpuan ni Felipe si Nathanael at sinabi sa kaniya, “Ang siyang naisulat sa kaustusan ni Moises at ng mga propeta - ay nakita namin, si Jesus na taga-Nazaret na anak ni Jose.”"},{"verse_number":46,"text":"Sinabi ni Nathanael, “Maaari bang may magandang bagay na magmula sa Nazaret?” Sinabi ni Felipe sa kaniya, “Halika at tingnan mo.”"},{"verse_number":47,"text":"Nakita ni Jesus na palapit si Nataniel sa kaniya at sinabi ang tungkol sa kaniya, “Tingnan ninyo, isa ngang tunay na Israelita, na walang panlilinlang.”"},{"verse_number":48,"text":"Sinabi sa kaniya ni Nataniel, “Papaano mo ako nakikilala?” Sumagot si Jesus at sinabi sa kaniya, “Bago ka tawagin ni Felipe, nang nasa ilalim ka ng puno ng igos, nakita na kita.”"},{"verse_number":49,"text":"Sumagot si Nathanael, “Rabi, ikaw ang Anak ng Diyos! Ikaw ang Hari ng Israel!”"},{"verse_number":50,"text":"Sumagot si Jesus at sinabi sa kaniya, “Dahil ba sa sinabi ko sa iyo, 'Nakita kita sa ilalim ng puno ng igos', naniniwala ka na? Makakakita ka ng mga bagay na mas higit pa kaysa dito.”"},{"verse_number":51,"text":"Sinabi ni Jesus, “Totoo, totoo itong sinasabi ko sa iyo, makikita mong magbukas ang mga kalangitan, at ang mga anghel ng Diyos ay umaakyat at bumababa sa kinaroroonan ng Anak ng Tao.”"}]},{"chapter_code":"JHN03","verses":[{"verse_number":1,"text":"Ngayon mayroon isang Pariseo na nagngangalang Nicodemo, kasapi ng Konseho ng Judio."},{"verse_number":2,"text":"Pumunta ang taong ito kay Jesus nang bandang gabi, at sinabi niya “Rabi, alam namin ikaw ay isang guro galing sa Diyos dahil walang sinumang makagagawa ng mga tandang ito na ginawa mo maliban na nasa kaniya ang Diyos.”"},{"verse_number":3,"text":"Sumagot si Jesus sa kanya, “Tunay nga, maliban kung isilang muli ang isang tao hindi niya makikita ang kaharian ng Diyos.”"},{"verse_number":4,"text":"Sinabi ni Nicodemo sa kaniya, “Paano ipapanganak ang isang tao kung siya ay matanda na? Hindi na siya pwedeng pumasok sa pangalawang pagkakataon sa sinapupunan ng kaniyang ina at ipanganak, kaya ba niya?”"},{"verse_number":5,"text":"Sumagot si Jesus, “Tunay nga, maliban kung ipinanganak ang isang tao sa tubig at sa Espiritu, hindi siya makakapasok sa kaharian ng Diyos."},{"verse_number":6,"text":"Iyong ipanganak sa laman ay laman, at iyong ipanganak sa Espiritu ay espritu."},{"verse_number":7,"text":"Huwag kayong mamangha na sinabi ko sa inyo, 'Dapat kayong ipanganak muli.'"},{"verse_number":8,"text":"Umiihip ang hangin kung saan niya gusto. Naririnig ninyo ang huni nito, ngunit hindi ninyo alam kung saan ito nagmula o kung saan ito pupunta. Gayon din naman ang sinumang isilang sa Espiritu.”"},{"verse_number":9,"text":"Sumagot si Nicodemo, sinasabi, “Paano mangyayari ang mga bagay na ito?”"},{"verse_number":10,"text":"Sinagot siya ni Jesus, “Ikaw ba ay guro ng Israel, at hindi mo naiintindihan ang mga bagay na ito?"},{"verse_number":11,"text":"Tunay nga, sinasabi namin iyong alam namin, at pinatotohanan iyong nakita namin. Subalit kayong mga tao, hindi ninyo tinatanggap ang aming patotoo."},{"verse_number":12,"text":"Kung sinabi ko sa iyo ang tungkol sa mga bagay na makalupa at hindi ka naniwala, paano ka maniniwala kung sasabihin ko sa iyo ang mga bagay na makalangit?"},{"verse_number":13,"text":"Walang sinumang umakyat sa langit maliban ang bumaba mula sa langit, ang Anak ng Tao."},{"verse_number":14,"text":"Tulad ng pagtaas ni Moises ng ahas sa ilang, gayon din naman ang Anak ng Tao ay kailangang maitaas,"},{"verse_number":15,"text":"upang ang lahat ng mananampalataya sa kaniya ay magkaroon ng buhay na walang hanggan."},{"verse_number":16,"text":"Dahil labis na inibig ng Diyos ang sangkatauhan, ibinigay niya ang kaniyang natatangi at nag-iisang Anak upang ang sinumang manalig sa kaniya ay hindi mamatay ngunit magkakaroon ng buhay na walang hanggan."},{"verse_number":17,"text":"Dahil hindi isinugo ng Diyos ang kaniyang Anak sa mundo para parusahan ang sangkatauhan, ngunit para ang mundo ay marapat na maligtas sa pamamagitan niya."},{"verse_number":18,"text":"Ang nananampalataya sa kaniya ay hindi mahatulan. Ang hindi nananampalataya ay nahatulan na dahil hindi siya nananampalataya sa pangalan ng natatanging Anak ng Diyos."},{"verse_number":19,"text":"Ito ang dahilan sa paghahatol, na ang ilaw ay dumating sa mundo, at minahal ng mga tao ang dilim kaysa ang liwanag dahil masama ang kanilang mga naging gawa."},{"verse_number":20,"text":"Dahil ang sinuman na gumagawa ng masama ay galit sa liwanag at hindi lumalapit sa ilaw upang ang kaniyang mga gawa ay hindi malantad."},{"verse_number":21,"text":"Subalit ang gumagawa ng katotohanan ay lumalapit sa liwanag upang ang kaniyang mga gawa ay malinaw na makita at ang mga iyon ay naganap dahil sa pagsunod sa Diyos.”"},{"verse_number":22,"text":"Pagkatapos nito, si Jesus at ang kaniyang mga alagad ay pumunta sa lupain ng Judea. Doon siya ay naglalaan ng panahon kasama nila at nagbabautismo."},{"verse_number":23,"text":"Ngayon si Juan din ay nagbabautismo sa Enon malapit sa Salim dahil higit na marami ang tubig doon. Lumalapit sa kaniya amg mga tao at sila ay nababautismuhan,"},{"verse_number":24,"text":"dahil hindi pa naipatapon sa bilangguan si Juan."},{"verse_number":25,"text":"Pagkatapos ay may lumitaw na alitan sa pagitan ng ilang alagad ni Juan at sa isang Judio tungkol sa seremonya ng paghuhugas."},{"verse_number":26,"text":"Pumunta sila kay Juan, at sinabi nila sa kanya “Rabi, yung kasama mo sa ibayo ng ilog Jordan, na iyong pinatotohanan, tingnan mo, nagbabautismo siya at pumupunta ang lahat sa kaniya.”"},{"verse_number":27,"text":"Sumagot si Juan, “Walang anumang bagay ang tatanggapin ng isang tao maliban na lamang kung ito ay ibinigay sa kaniya mula sa langit."},{"verse_number":28,"text":"Kayo mismo ang makapagpapatunay na sinabi ko, 'Hindi ako ang Cristo' sa halip sinabi ko, 'Isinugo ako bago pa siya.”"},{"verse_number":29,"text":"Ang kasama ng ikakasal na babae ay ang ikakasal na lalaki. Ngayon ang kaibigan ng ikakasal na lalaki, na siyang nakatayo at nakikinig, ay labis ang tuwa dahil sa tinig ng ikakasal na lalaki. Ito ngang aking kagalakan ay naging ganap."},{"verse_number":30,"text":"Siya ay dapat maitaas, subalit ako ay dapat maibaba."},{"verse_number":31,"text":"Ang mula sa kaitaasan ay nakatataas sa lahat. Ang taga lupa ay nagmula sa lupa at nagsasalita ng mga bagay na makalupa. Ang mula sa langit ay nakatataas sa lahat."},{"verse_number":32,"text":"Nagpapatotoo siya kung ano ang kaniyang nakita at narinig, ngunit walang taong tumatanggap sa kaniyang patotoo."},{"verse_number":33,"text":"Ang tumanggap sa kaniyang patotoo ay pinatunayan na totoo ang Diyos."},{"verse_number":34,"text":"Dahil ang sinumang ipinadala ng Diyos ay ipinapahayag ang mga salita ng Diyos. Dahil hindi niya ibinigay ang Espiritu sa pamamagitan ng sukat."},{"verse_number":35,"text":"Mahal ng Ama ang Anak at ibinigay niya ang lahat sa kaniyang mga kamay."},{"verse_number":36,"text":"Ang nananampalataya sa Anak ay may buhay na walang hanggan, ngunit ang sinumang hindi sumusunod sa Anak ay hindi makakakita ng buhay, kundi mananatili ang poot ng Diyos sa kaniya.”"}]},{"chapter_code":"JHN14","verses":[{"verse_number":1,"text":"Huwag ninyong hayaan mabalisa ang inyong puso. Manampalataya kayo sa Diyos; manampalataya rin kayo sa akin."},{"verse_number":2,"text":"Sa tahanan ng aking Ama ay maraming mga tirahan; Kung hindi gayon, sinabi ko na sana sa inyo; sapagka't aalis ako upang maghanda ng tirahan para sa inyo."},{"verse_number":3,"text":"Kung aalis ako at maghanda ng matititrahan ninyo, ako ay muling babalik at tatanggapin kayo sa aking sarili, upang kung saan man ako, kayo ay naroon din."},{"verse_number":4,"text":"Alam ninyo ang daan kung saan ako pupunta.”"},{"verse_number":5,"text":"Sinabi ni Tomas kay Jesus, “Panginoon, hindi namin alam kung saan kayo pupunta, papaano namin malalaman ang daan?"},{"verse_number":6,"text":"Sabi ni Jesus sa kaniya, “Ako ang daan, ang katotohanan, at ang buhay; walang sinuman ang makararating sa Ama maliban sa pamamagitan ko."},{"verse_number":7,"text":"Kung nakilala mo na ako, dapat kilala mo na rin ang aking Ama; mula ngayon kilala mo na siya at nakita mo na siya.”"},{"verse_number":8,"text":"Ang sabi ni Felipe kay Jesus, “Panginoon, ipakita mo sa amin ang Ama, at iyon ay sapat na sa amin”."},{"verse_number":9,"text":"Ang sabi ni Jesus sa kaniya, “Felipe, hindi ba matagal na akong kasama ninyo, at hindi mo pa rin ako nakikilala? Kung sinuman ang nakakita sa akin, nakakita sa Ama; paano mo nasasabi, 'Ipakita sa amin ang Ama'?"},{"verse_number":10,"text":"Hindi ka ba naniniwala na ako ay nasa Ama at ang Ama ay nasa akin? Ang mga salitang sinasabi ko sa inyo ay sinasabi ko hindi sa aking sariling kapasyahan; sa halip, ito ay ang Ama na nananahan sa akin na siyang gumagawa ng kaniyang gawain."},{"verse_number":11,"text":"Maniwala kayo sa akin, na ako ay nasa Ama, at ang Ama ay nasa akin; o kaya, maniwala kayo sa akin dahil sa mismo kong ginagawa."},{"verse_number":12,"text":"Tunay nga ang sinasabi ko sa inyo, sinuman ang sumasampalataya sa akin, sa mga gawain na ginagawa ko, gagawin niya rin itong mga ginagawa ko; at gagawa siya ng mas higit na dakilang mga gawain dahil ako ay pupunta sa Ama."},{"verse_number":13,"text":"Anuman ang inyong hingin sa aking pangalan, gagawin ko upang ang Ama ay maluluwalhati sa Anak."},{"verse_number":14,"text":"Kung anuman ang inyong hingin sa aking pangalan, iyon ay gagawin ko."},{"verse_number":15,"text":"Kung mahal ninyo ako, susundin ninyo ang aking mga kautusan."},{"verse_number":16,"text":"At mananalangin ako sa Ama, at bibigyan niya kayo ng isa pang Manga-aliw upang siya ay sumainyo magpakailanman,"},{"verse_number":17,"text":"na ang Espiritu ng katotohanan. Hindi siya maaaring tanggapin ng mundo dahil hindi siya nakikita nito o nakikilala man. Subalit, kayo, kilala ninyo siya, dahil nanatili siya sa inyo at sasainyo."},{"verse_number":18,"text":"Hindi ko kayo iiwanan nang nag-iisa. Babalik ako sa inyo."},{"verse_number":19,"text":"Sa sandaling panahon, hindi na ako makikita ng mundo, ngunit makikita ninyo ako. Sapagkat nabubuhay ako, mabubuhay din kayo."},{"verse_number":20,"text":"Sa araw na iyon, malalaman ninyo na ako ay nasa Ama, at kayo ay nasa akin, at ako ay nasa inyo."},{"verse_number":21,"text":"Ang sinuman na mayroon ng aking mga kautusan at isinasagawa ang mga ito; siya ang nagmamahal sa akin; at siya na nagmamahal sa akin ay mamahalin ng aking Ama, at mamahalin ko rin siya, at ipakikita ko sa kaniya ang aking sarili.”"},{"verse_number":22,"text":"Sinabi ni Judas (hindi si Iscariote) kay Jesus, “Panginoon, ano ang nangyayari na inyong ipakikita ang iyong sarili sa amin at hindi sa mundo?”"},{"verse_number":23,"text":"Sumagot si Jesus at sinabi sa kaniya: “Kung sinuman ang magmamahal sa akin, isasagawa niya ang aking salita. Mamahalin siya ng aking Ama, at kami ay paparoon sa kaniya at gagawa kami ng aming tirahan kasama niya."},{"verse_number":24,"text":"Ang sinumang hindi nagmamahal sa akin ay hindi isinasagawa ang aking mga salita. Ang salitang inyong naririnig ay hindi sa akin, ngunit sa Ama na nagsugo sa akin."},{"verse_number":25,"text":"Sinabi ko na sa inyo ang mga bagay na ito, habang ako ay nabubuhay pa kasama ninyo."},{"verse_number":26,"text":"Subalit, ang Manga-aliw na ang Banal na Espiritu na ipapadala ng Ama sa aking pangalan ay magtuturo sa inyo ng lahat ng mga bagay at magpapaalala ng lahat ng aking sinabi sa inyo."},{"verse_number":27,"text":"Kapayapaan ang iiwan ko sa inyo; ibinibigay ko ang aking kapayapaan sa inyo. Hindi ko ito ibinibigay katulad ng pagbibigay ng mundo. Huwag hayaang mabalisa ang inyong puso, at huwag ito hayaang matakot."},{"verse_number":28,"text":"Narinig ninyo ang sinabi ko sa inyo, “Ako ay aalis, at babalik ako sa inyo'. Kung minahal ninyo ako, nagagalak na sana kayo dahil pupunta ako sa Ama, sapagkat ang Ama ay higit na dakila kaysa sa akin."},{"verse_number":29,"text":"Ngayon nasabi ko na sa inyo bago pa ito mangyayari upang kung mangyari man ito, kayo ay maaring maniwala."},{"verse_number":30,"text":"Hindi na ako masyadong magsasalita sa inyo, dahil darating na ang prinsipe ng mundong ito. Wala siyang kapangyarihan sa akin,"},{"verse_number":31,"text":"ngunit upang malaman ng mundo na mahal ko ang Ama, ginagawa ko kung ano ang inuutos ng Ama sa akin, katulad lamang ng pagbigay niya sa akin ng kautusan. Magsitindig na kayo, umalis na tayo sa lugar na ito.”"}]},{"chapter_code":"1JN01","verses":[{"verse_number":1,"text":"Na kung alinman mula sa simula- na aming narinig, na nakita ng aming mga mata, na aming natunghayan, at nahawakan ng aming mga kamay-patungkol sa Salita ng buhay."},{"verse_number":2,"text":"At ang buhay ay nagawang ipaalam, at aming nakita, at nasaksihan, at hinayag sa inyo ang buhay na walang hanggan, na noon ay kasama ng Ama, at nagawang ipaalam sa amin."},{"verse_number":3,"text":"Iyon na aming nakita at narinig inihayag din namin sa inyo, sa gayon ay magkaroon kayo ng pakikisama sa amin, at ang aming pakikisama ay kasama ang Ama at kasama ang kanyang Anak na si Jesu-Cristo."},{"verse_number":4,"text":"At sinulat namin ang mga bagay na ito sa inyo upang ang aming kagalakan ay maging ganap."},{"verse_number":5,"text":"Ito ang mensahe na aming narinig mula sa kanya at ipinapahayag sa inyo: Ang Diyos ay liwanag at sa kanya'y walang kadiliman ang lahat."},{"verse_number":6,"text":"Kung sinasabi natin na tayo ay mayroong pakikisama sa Kanya at lumalakad sa kadiliman, tayo ay nagsisinungaling at hindi isinasagawa ang katotohanan."},{"verse_number":7,"text":"Pero kung tayo'y lumalakad sa liwanag katulad niyang nasa liwanag, meron tayong pakikisama sa isa't isa at ang dugo ni Jesus na kanyang Anak ay naglilinis sa atin mula sa lahat ng kasalanan."},{"verse_number":8,"text":"Kung sinasabi natin na wala tayong kasalanan, niloloko natin ang ating mga sarili at ang katotohanan ay wala sa atin."},{"verse_number":9,"text":"Pero kung tayo ay umamin sa ating mga kasalanan, siya ay matapat at matuwid na patawarin tayo sa ating mga kasalanan at linisin tayo mula sa lahat ng kasamaan."},{"verse_number":10,"text":"Kapag sinabi natin na hindi tayo nagkasala, ginawa natin siyang isang sinungaling, at ang kanyang salita ay wala sa atin."}]},{"chapter_code":"1JN05","verses":[{"verse_number":1,"text":"Kung sinuman ang naniniwala na si Jesus ay ang Cristo na ipinanganak sa Diyos. At kung sinuman ang nagmamahal sa kanya na nagmula sa Ama ay minamahal din ang kanyang mga anak."},{"verse_number":2,"text":"Sa pamamagitan nito malalaman natin na mahal natin ang mga anak ng Diyos-kung mahal natin ang Diyos at ginagawa ang kanyang mga kautusan."},{"verse_number":3,"text":"Sapagkat ito ang pagmamahal para sa Diyos-nananatili tayo sa kanyang mga kautusan. At ang kanyang mga kautusan ay hindi pasanin."},{"verse_number":4,"text":"Ang sinumang ipinanganak sa Diyos ay napagtagumpayan ang mundo. At ito ang pagwawagi na napagtagumpayan ng mundo, kahit ang ating pananampalataya."},{"verse_number":5,"text":"Sino ba siyang napapagtagumpayan ang mundo? Siya na naniniwala na si Jesus ay ang Anak ng Diyos."},{"verse_number":6,"text":"Ito ang siya na dumating sa pamamagitan ng tubig at dugo-Jesu-Cristo. Siya ay dumating hindi lamang sa pamamagitan ng tubig, kundi sa pamamagitan ng tubig at dugo."},{"verse_number":7,"text":"Sapagkat mayroong tatlo na siyang nagpapatunay"},{"verse_number":8,"text":"ang Espiritu, ang tubig at ang dugo. Ang tatlong ito ay nagkakasundo."},{"verse_number":9,"text":"Kung tinatanggap natin ang patotoo ng tao, ang patotoo ng Diyos ay mas dakila. Sapagkat ang patotoo ng Diyos ay ito- na siya'y nagdala ng patunay patungkol sa kanyang Anak."},{"verse_number":10,"text":"Siya na naniniwala sa Anak ng Diyos ay may patotoo sa kanyang sarili. Sinumang hindi naniniwala sa Diyos ay ginawa siyang sinungaling, dahil hindi siya naniwala sa patotoo na binigay ng Diyos patungkol sa kanyang Anak."},{"verse_number":11,"text":"At ang patotoo ay ito- na tayo ay binigyan ng Diyos ng buhay na walang hanggan, at ang buhay na ito ay nasa kanyang Anak."},{"verse_number":12,"text":"Siya na pinananahanan ng Anak ay may buhay. Siya na hindi pinananahanan ng Anak ng Diyos ay walang buhay."},{"verse_number":13,"text":"Ang mga bagay na ito ay sinulat ko sa inyo para malaman ninyo na mayroon kayong buhay na walang hanggan-sa inyo na naniniwala sa pangalan ng Anak ng Diyos."},{"verse_number":14,"text":"At ito ang pananalig na mayroon tayo sa kanyang harapan, na kung anuman ang hilingin natin ayon sa kanyang kalooban, naririnig niya tayo."},{"verse_number":15,"text":"At kung alam natin na pinapakinggan niya tayo-anuman ang hiling natin sa kanya-alam nating mayroon na tayo ng anumang hiniling natin sa kanya."},{"verse_number":16,"text":"Kung sinuman ang nakakakita sa kanyang kapatid na gumagawa ng kasalanan na hindi humahantong sa kamatayan, kailangan niya manalangin at siya ay bibigyan ng Diyos ng buhay. Ang tinutukoy ko ay ang pagkakasala na hindi nagdadala sa kamatayan. Mayroong kasalanan na nagdadala sa kamatayan-hindi ko sinasabi na kailangan niyang ipanalangin ang tungkol doon."},{"verse_number":17,"text":"Lahat ng hindi matuwid ay kasalanan- pero may kasalanan na hindi nagdadala sa kamatayan."},{"verse_number":18,"text":"Alam natin na kung sinuman ang ipinanganak sa Diyos ay hindi nagkakasala. Pero siya na ipinanganak sa Diyos ay iniingatan niya, at hindi siya mapipinsala ng masama."},{"verse_number":19,"text":"Alam natin na tayo ay sa Diyos, at alam natin na ang buong mundo ay nasa ilalim ng kapangyarihan ng masama."},{"verse_number":20,"text":"Pero alam natin na ang Anak ng Diyos ay dumating at binigyan tayo ng kaunawaan, na kilala natin siya na totoo, at tayo ay nasa kanya na siyang totoo- kahit na sa kanyang Anak na si Jesu-Cristo. Siya ang totoong Diyos at buhay na walang hanggan."},{"verse_number":21,"text":"Minamahal kong mga anak, lumayo kayo sa mga diyos-dyosan."}]},{"chapter_code":"1JN03","verses":[{"verse_number":1,"text":"Masdan kung anong uri ng pag-ibig ng Ama ang ibinigay sa atin, na tayo ay nararapat tawaging mga anak ng Diyos, at ito ang kung ano tayo. Sa dahilang ito, hindi tayo kilala ng mundo dahil hindi siya kilala nito."},{"verse_number":2,"text":"Mga minamahal, ngayon tayo ay mga anak ng Diyos, at hindi pa naipahayag kung magiging ano tayo. Alam natin na kapag magpakita si Cristo, tayo ay magiging katulad niya, dahil makikita natin siya bilang siya."},{"verse_number":3,"text":"At bawat isa na may ganitong pagtitiwala tungkol sa hinaharap na nakatuon sa kanya ay dinadalisay ang kanyang sarili tulad ng siya ay dalisay."},{"verse_number":4,"text":"Ang lahat ng patuloy na nagkakasala ay gumagawa ng kung ano ang labag sa batas. Dahil ang kasalanan ay ang paglabag sa batas."},{"verse_number":5,"text":"Alam niyo na nahayag si Cristo upang sa gayon ay alisin ang mga kasalanan. At sa kanya ay walang kasalanan."},{"verse_number":6,"text":"Walang sinumang nananatili sa kanya na patuloy na nagkakasala. Walang sinumang patuloy sa pagkakasala ang nakakita sa kanya o nakakila sa kanya."},{"verse_number":7,"text":"Minamahal kong mga anak, huwag ninyong hayaan ang sinuman na akayin kayo sa ligaw na landas. Siya na gumagawa ng katuwiran ay matuwid, gaya ni Cristo na matuwid."},{"verse_number":8,"text":"Siya na gumagawa nang kasalanan ay sa diablo, sapagkat ang diablo ay nagkasala na mula pa sa simula. Sa dahilang ito, ang Anak ng Diyos ay nahayag, upang kanyang mawasak ang mga gawa ng diablo."},{"verse_number":9,"text":"Ang sinumang isinilang sa Diyos ay hindi nagkasala dahil ang binhi ng Diyos ay nananatili sa kanya. Hindi siya makapagpatuloy na magkasala dahil isinilang siya sa Diyos."},{"verse_number":10,"text":"Dito ang mga anak ng Diyos at ang mga anak ng diablo ay nahayag. Ang sinumang hindi gumagawa kung ano ang matuwid ay hindi sa Diyos, ni ang sinumang hindi nagmamahal ng kanyang kapatid."},{"verse_number":11,"text":"Sapagkat ito ang mensaheng narinig na ninyo mula pa sa simula, na dapat mahalin natin ang bawat isa,"},{"verse_number":12,"text":"hindi katulad ni Cain na siyang nasa kasamaan at pinatay ang kanyang kapatid. At bakit niya nagawang siya ay patayin? Dahil masama ang kanyang mga gawa, at ang kanyang kapatid ay matuwid."},{"verse_number":13,"text":"Huwag kayong magtaka mga kapatid, kapag ang mundo ay napopoot sa inyo."},{"verse_number":14,"text":"Alam natin na tayo ay lumipat na mula sa kamatayan patungo sa buhay, dahil mahal natin ang mga kapatid. Ang sinumang hindi umiibig ay nanatili sa kamatayan."},{"verse_number":15,"text":"Ang sinumang napopoot sa kanyang kapatid ay mamamatay tao. At alam ninyo na ang buhay na walang hanggan ay hindi nanatili sa isang mamamatay tao."},{"verse_number":16,"text":"Sa pamamagitan nito alam natin ang pag-ibig, sapagkat inialay ni Cristo ang kanyang buhay para sa atin. Nararapat din nating ialay ang ating mga buhay para sa mga kapatid."},{"verse_number":17,"text":"Pero ang sinumang mayroong mga mabubuting bagay sa mundo, nakitang nangangailangan ang kapatid, at isinara ang kanyang maawaing puso sa kanya, papaano mananatili sa kanya ang pag-ibig ng Diyos?"},{"verse_number":18,"text":"Mga minamahal kong mga anak, huwag tayong magmahal sa salita o sa dila, pero sa mga gawa at katotohanan."},{"verse_number":19,"text":"Sa pamamagitan nito alam natin na tayo ay nasa katotohanan at tinitiyak natin ang ating mga puso sa kanyang harapan."},{"verse_number":20,"text":"Sapagkat kapag sinusumpa tayo ng ating mga puso, mas dakila ang Diyos kaysa sa ating mga puso, at alam niya ang lahat ng mga bagay."},{"verse_number":21,"text":"Mga minamahal, kapag hindi tayo isinisumpa ng mga puso natin, may kapanatagan tayo sa Diyos."},{"verse_number":22,"text":"At anuman ang hihilingin natin, matatanggap natin mula sa kanya, dahil pinanatili natin ang kanyang mga kautusan at ginagawa ang mga bagay na kalugud-lugod sa kanyang paningin."},{"verse_number":23,"text":"At ito ang kanyang kautusan - na tayo ay dapat maniwala sa pangalan ng kanyang Anak na si Jesu-Cristo at mahalin ang bawat isa - gaya ng ibinigay niyang kautusan sa atin."},{"verse_number":24,"text":"Siya na pinapanatili ang kautusan ng Diyos ay nananatili sa kanya, at ang Diyos ay nananatili sa kanya. At sa pamamagitan nito alam natin na siya ay nananatili sa atin, sa pamamagitan ng Espiritu na ibinigay niya sa atin."}]},{"chapter_code":"PSA136","verses":[{"verse_number":1,"text":"O, magpasalamat kay Yahweh; dahil siya ay mabuti, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman."},{"verse_number":2,"text":"O, magpasalamat sa Diyos ng mga diyos, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman."},{"verse_number":3,"text":"O, magpasalamat sa Panginoon ng mga panginoon, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman."},{"verse_number":4,"text":"Sa kaniya na nag-iisang gumagawa ng labis na kamanghaan, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":5,"text":"sa kaniyang karunungan ginawa ang kalangitan, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":6,"text":"sa kaniya na nagkalat ng lupa sa ibabaw ng katubigan, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":7,"text":"sa kaniya na gumawa ng kahanga-hangang mga liwanag, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":8,"text":"ng araw na naghahari sa umaga, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":9,"text":"ng buwan at bituin na naghahari sa gabi, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":10,"text":"na siyang pumatay sa mga panganay na anak ng Ehipto, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":11,"text":"at naglabas sa Israel mula sa kanila, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":12,"text":"na may malakas na kamay at nakataas na braso, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":13,"text":"na siyang naghati sa dagat na Pula dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":14,"text":"at nagawang padaanin ang Israelita sa kalagitnaan nito, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":15,"text":"pero ipinatapon ang Paraon at ang kaniyang hukbo sa dagat na Pula, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":16,"text":"siya na nagdala sa kaniyang bayan sa ilang, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":17,"text":"siya na nagpapatay sa mga dakilang hari, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":18,"text":"at pinatay ang tanyag na mga hari, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":19,"text":"sina Sihon hari ng mga Amoreo, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":20,"text":"at Og hari ng Bashan, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":21,"text":"at binigay ang kanilang lupain bilang pamana, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":22,"text":"isang pamana sa Israel na kaniyang lingkod, dahil ang kaniyang katapatan sa tipan ay mananatili magpakailanman—"},{"verse_number":23,"text":"siyang umalala sa atin at tumulong sa ating kahihiyan, dahil ang kaniyang katapatan sa tipan ay nananatili magpakailanman—"},{"verse_number":24,"text":"at siyang nagbigay sa atin ng katagumpayan sa ating mga kaaway, dahil ang kaniyang katapatan sa tipan ay nananatili magpakailanman—"},{"verse_number":25,"text":"siyang nagbibigay ng pagkain sa lahat ng nabubuhay, dahil ang kaniyang katapatan sa tipan ay nananatili magpakailanman."},{"verse_number":26,"text":"O, magpasalamat sa Diyos sa langit, dahil ang kaniyang katapatan sa tipan ay nananatili magpakailanman."}]},{"chapter_code":"PSA029","verses":[{"verse_number":1,"text":"Kilalanin na si Yahweh— kayo na mga anak ng makapangyarihan— kilalanin na si Yahweh ay may kaluwalhatian at kapangyarihan!"},{"verse_number":2,"text":"Ibigay kay Yahweh ang karangalan na nararapat sa kaniyang pangalan; sambahin si Yahweh sa pananamit na naaangkop para sa kaniyang kabanalan."},{"verse_number":3,"text":"Ang tinig ni Yahweh ay naririnig sa ibabaw ng mga katubigan; dumadagundong ang Diyos ng kaluwalhatian, dumadagundong si Yahweh sa ibabaw ng katubigan."},{"verse_number":4,"text":"Ang tinig ni Yahweh ay makapangyarihan; ang tinig ni Yahweh ay kamangha-mangha. Ang tinig ni Yahweh ay nakawawasak ng mga sedar;"},{"verse_number":5,"text":"Ang tinig ni Yahweh ay napagpipira-piraso ang mga sedar ng Lebanon."},{"verse_number":6,"text":"Pinalulukso niya ang Lebanon tulad ng isang guya at ang Sirion tulad ng isang batang baka."},{"verse_number":7,"text":"Bumubuga ng lumalagablab na apoy ang tinig ni Yahweh."},{"verse_number":8,"text":"Ang tinig ni Yahweh ang yumayanig sa ilang; si Yahweh ang yumayanig sa ilang ng Kades."},{"verse_number":9,"text":"Ang tinig ni Yahweh ang nagdudulot na manganak ang babaeng usa; kinakalbo nito ang mga gubat; pero sa kaniyang templo ang lahat ay nagsasabing, “Kaluwalhatian!”"},{"verse_number":10,"text":"Si Yahweh ay umuupo bilang hari sa ibabaw ng baha; si Yahweh ay umuupo bilang hari magpakailanman."},{"verse_number":11,"text":"Si Yahweh ang nagbibigay-lakas sa kaniyang bayan; Pinagpapala ni Yahweh ng kapayapaan ang kaniyang bayan."}]},{"chapter_code":"PSA138","verses":[{"verse_number":1,"text":"Magpapasalamat ako sa iyo ng buong puso; aawitan kita ng mga papuri sa harap ng mga diyos-diyosan."},{"verse_number":2,"text":"Luluhod ako sa iyong banal na templo at magpapasalamat sa iyong ngalan para sa katapatan sa tipan at sa iyong pagiging mapagkakatiwalaan. Dinakila mo ang iyong salita at iyong pangalan higit sa lahat."},{"verse_number":3,"text":"Sa araw na tumawag ako sa iyo, sinagot mo ako; pinalakas mo ang aking loob at ang aking kaluluwa."},{"verse_number":4,"text":"Yahweh, lahat ng hari sa mundo ay magpapasalamat sa iyo dahil maririnig nila ang mga salita ng iyong bibig."},{"verse_number":5,"text":"Tunay nga na aawitin nila ang mga ginawa ni Yahweh, dahil dakila ang kaluwalhatian ni Yahweh."},{"verse_number":6,"text":"Kahit na mataas si Yahweh, sa mga mabababa siya nag-aaruga, pero malayo sa kaniya ang mga mapagmalaki."},{"verse_number":7,"text":"Kahit na lumakad ako sa kalagitnaan ng kapamahakan, pangangalagaan mo ang aking buhay; iuunat mo ang iyong kamay laban sa galit ng aking mga kaaway, at ililigtas ako ng iyong kanang kamay."},{"verse_number":8,"text":"Kasama ko si Yahweh hanggang sa huli; Yahweh panatilihin mo ang iyong katapatan sa tipan magpakailanman; huwag mong pabayaan ang mga nilikha ng iyong mga kamay."}]},{"chapter_code":"DEU30","verses":[{"verse_number":1,"text":"Kapag ang lahat ng mga bagay na ito ay nakarating sa inyo, ang mga pagpapala at ang mga sumpa na itinalaga ko sa harapan ninyo, at kapag isinaisip ninyo ito kasama ang lahat ng ibang mga bansa kung saan si Yahweh ang inyong Diyos ay dinala kayo,"},{"verse_number":2,"text":"at kapag bumalik kayo kay Yahweh na inyong Diyos at sumunod sa kaniyang boses, susundin ang lahat ng mga sinasabi ko sa inyo sa araw na ito— kayo at inyong mga anak— ng inyong buong puso at inyong buong kaluluwa,"},{"verse_number":3,"text":"kung gayon babaligtarin ni Yahweh na inyong Diyos ang inyong pagkakabihag at magkakaroon ng habag sa inyo, babalik siya at titipunin kayo mula sa lahat ng mga tao kung saan si Yahweh ang inyong Diyos ay ikinalat kayo."},{"verse_number":4,"text":"Kung mayroon sa mga lahi ninyo ang ipinatapon sa pinaka-malalayong mga lugar mula sa ilalim ng kalangitan, mula kung saan si Yahweh na inyong Diyos ay titipunin kayo, at magmula doon dadalhin niya kayo."},{"verse_number":5,"text":"Si Yahweh na inyong Diyos ay dadalhin kayo sa lupain na pagmamay-ari ng inyong mga ninuno, at magiging sa inyo ulit ito; Gagawan ka niya ng kabutihan at pararamihin kayo higit pa sa ginawa niya sa inyong mga ninuno."},{"verse_number":6,"text":"Tutuliin ni Yahweh na inyong Diyos ang inyong puso at ang puso ng inyong mga kaapu-apuhan para mamahalin ninyo si Yahweh na inyong Diyos ng inyong buong puso at inyong buong kaluluwa, para kayo ay mabuhay."},{"verse_number":7,"text":"Ilalagay ni Yahweh na inyong Diyos itong mga sumpa sa inyong mga kaaway at sa mga galit, at sa sinumang nagpapahirap sa inyo."},{"verse_number":8,"text":"Babalik kayo at susunod sa boses ni Yahweh, at gagawin ninyo ang lahat ng kaniyang mga utos na inuutos ko sa inyo sa araw na ito."},{"verse_number":9,"text":"Si Yahweh na inyong Diyos ay gagawing masagana ang lahat ng ginawa ng inyong kamay sa bunga ng inyong katawan, sa bunga ng inyong mga baka, at sa bunga ng inyong mga pananim, para sa kasaganahan, para kay Yahweh muling masisiyahan ulit siya sa inyo sa kasaganahan, gaya ng pagkalugod niya sa inyong mga ninuno."},{"verse_number":10,"text":"Gagawin niya ito kung susundin ninyo ang salita ni Yahweh na inyong Diyos, para panatilihin ang kaniyang mga kautusan at mga batas na nasusulat sa aklat ng kautusan, kung babalik kayo kay Yahweh na inyong Diyos ng inyong buong puso at inyong buong kaluluwa."},{"verse_number":11,"text":"Dahil itong utos na sinasabi ko sa inyo sa araw na ito ay hindi lubhang mahirap para sa inyo, ni ito ay napakalayo sa inyo para abutin,"},{"verse_number":12,"text":"hindi ito nasa langit, para sabihin ninyo, “Sinong nais umakyat sa atin sa langit at dalhin ito pababa sa atin at maaari nating marinig ito, para magawa natin ito?'"},{"verse_number":13,"text":"Maging ito ay sa ibayo ng dagat, para inyong masabi, 'Sino sa atin ang pupunta sa ibayong dagat para dalhin ito sa atin at marinig natin, at para magawa natin ito?'"},{"verse_number":14,"text":"Pero ang salita ay napakalapit sa inyo, nasa inyong bibig at nasa inyong puso, para inyong magawa ito."},{"verse_number":15,"text":"Tingnan ninyo, inilagay ko sa araw na ito sa inyong harapan ang buhay at kabutihan, kamatayan at kasamaan."},{"verse_number":16,"text":"Kung susundin ninyo ang mga panuntunan ni Yahweh na inyong Diyos, na sinasabi ko sa inyo sa araw na ito na mahalin si Yahweh na inyong Diyos, para mamuhay ng naaayon sa kaniyang paraan, at sundin ang kaniyang mga kautusan, ang kaniyang mga batas at kaniyang mga ordenansa, mabubuhay kayo at paparamihin, at pagpalain kayo ni Yahweh na inyong Diyos sa lupain na inyong pupuntahan para angkinin."},{"verse_number":17,"text":"Pero kung ang inyong puso ay tumalikod at hindi kayo nakinig sa halip ay lumayo at nagpatirapa pababa sa ibang mga diyus-diyosan at sasambahin sila,"},{"verse_number":18,"text":"kung gayon, sasabihin ko sa inyo sa araw na ito siguradong mamamatay kayo, hindi tatagal ang inyong buhay sa lupain na inyong dadaanan sa kabila ng Jordan para puntahan at angkinin."},{"verse_number":19,"text":"Tinatawag ko ang langit at ang lupa para maging saksi laban sa inyo sa araw na ito, itinalaga ko sa inyo ang buhay at kamatayan, ang mga pagpapala at mga sumpa, kaya piliin ninyo ang buhay para kayo at ang inyong lahi ay mamuhay ng matagal."},{"verse_number":20,"text":"Gawin ito para mahalin si Yahweh na inyong Diyos, para sundin ang kaniyang salita, at para kumapit sa kaniya. Dahil siya ang inyong buhay at ang haba ng inyong mga araw, gawin ninyo ito para maaari kayong mamuhay sa lupain na ipinangako ni Yahweh sa inyong mga ninuno, kay Abraham, kay Isaac, at kay Jacob, na ibibigay sa kanila.”"}]},{"chapter_code":"EZK33","verses":[{"verse_number":1,"text":"dumating ang salita ni Yahweh sa akin at sinabi,"},{"verse_number":2,"text":"“Anak ng tao, ipahayag mo ito sa iyong mga tao; sabihin mo sa kanila, 'Kapag magdadala ako ng isang espada laban sa anumang lupain, at ang mga tao sa lupaing iyon ay kukuha ng isang lalaki mula sa kanila at gagawin siyang isang tagapagbantay para sa kanila."},{"verse_number":3,"text":"Titingnan niya kung may paparating na espada sa lupain, at hihipan niya ang kaniyang trumpeta upang bigyan ng babala ang mga tao!"},{"verse_number":4,"text":"Kung marinig ito ng mga tao at hindi nila binigyang pansin, at kung dumating ang espada at pinatay silang lahat, at ang dugo ng bawat isa ay nasa sarili na nitong ulo."},{"verse_number":5,"text":"Kung sinumang makarinig sa tunog ng trumpeta ngunit hindi niya binigyang pansin, ang kaniyang dugo ay nasa sa kaniya; ngunit kung binigyan niya ng pansin, maililigtas niya ang sariling buhay."},{"verse_number":6,"text":"Gayunman, kung makita ng tagapagbantay na paparating ang espada, ngunit hindi niya hinipan ang trumpeta, ang kahihinatnan nito ay hindi nabigyang babala ang mga tao, at kung dumating ang espada at kukunin ang buhay ng sinuman, kung gayon, namatay ang taong iyon sa kaniyang sariling kasalanan, ngunit hahanapin ko ang kaniyang dugo mula sa tagapagbantay.'"},{"verse_number":7,"text":"Ngayon ikaw mismo, anak ng tao! Ginawa kitang isang tagapagbantay sa buong sambahayan ng Israel; mapapakinggan mo ang mga salita mula sa aking bibig at balaan mo sila sa halip na ako."},{"verse_number":8,"text":"Kung sasabihin ko sa isang masamang tao, 'Masamang tao, ikaw ay tiyak na mamamatay!' ngunit kung hindi mo ito ipinahayag para bigyang babala ang masama tungkol sa kaniyang pamamaraan at siyang masama ay mamamatay sa kaniyang kasalanan, ngunit hahanapin ko ang kaniyang dugo mula sa iyong kamay!"},{"verse_number":9,"text":"Ngunit ikaw, kung binalaan mo ang masama tungkol sa kaniyang pamamaraan, para sa ganoon ay matalikuran niya ito, at kung hindi niya tatalikuran ang kaniyang pamamaraan, mamamatay siya sa kaniyang kasalanan, ngunit maliligtas mo ang iyong sariling buhay."},{"verse_number":10,"text":"Kaya ikaw, anak ng tao, sabihin mo sa sambahayan ng Israel, 'Sinasabi ninyo ito: Ang aming pagsuway at ang aming mga kasalanan ay nasa amin, at nabubulok kami dahil dito! Paano kami mabubuhay?'"},{"verse_number":11,"text":"Sabihin mo sa kanila, 'Buhay ako—ito ang pahayag ng Panginoong Yahweh—. Hindi ko ikinagagalak ang kamatayan ng masama, sapagkat kung pagsisisihan ng masama ang kaniyang pamamaraan, kung gayon mabubuhay siya! Magsisi kayo! Magsisi kayo mula sa mga masasama ninyong pamamaraan! Sapagkat bakit ninyo kailangang mamatay, sambahayan ng Israel?'"},{"verse_number":12,"text":"At ikaw, anak ng tao, sabihin mo sa iyong mga tao, 'Ang pagkamatuwid ng isang matuwid na tao ay hindi makapagliligtas sa kaniya kung magkakasala siya! At ang kasamaan ng masamang tao ay hindi magdudulot sa kaniya ng kamatayan kung pagsisisihan niya ang kaniyang kasalanan. Sapagkat ang taong matuwid ay hindi mabubuhay dahil sa kaniyang pagkamatuwid kung siya ay magkakasala."},{"verse_number":13,"text":"Kung sasabihin ko sa matuwid na “Tiyak na mabubuhay siya!” at kung magtitiwala siya sa sarili niyang pagkamatuwid at pagkatapos makagawa siya ng hindi makatarungan, hindi ko na iisipin pa ang anumang kaniyang pagkamatuwid, mamamatay siya sa kasamaan na kaniyang nagawa."},{"verse_number":14,"text":"At kung sasabihin ko sa masama, “siguradong mamamatay ka!” ngunit kung pagsisisihan niya ang kaniyang mga kasalanan at gagawin kung ano ang makatarungan at tama—"},{"verse_number":15,"text":"kung isasauli niya ang garantiya ng sangla na sapilitang hiningi niya, o kung isasauli niya kung ano ang kaniyang ninakaw, at lalakad sa mga alituntunin ng batas na nagbibigay buhay at hindi na kailanman gagawa ng anumang kasalanan, tiyak na mabubuhay siya at hindi mamamatay."},{"verse_number":16,"text":"Wala na sa kaniyang mga nagawang kasalanan ang aking iisipin para sa kaniya. Kumilos siya ng makatarungan at makatuwiran, kaya siguradong mabubuhay siya!"},{"verse_number":17,"text":"Ngunit sinasabi ng iyong mga tao, “Hindi patas ang kaparaanan ng Panginoon!” ngunit ang inyong mga kaparaanan ang hindi patas!"},{"verse_number":18,"text":"Kapag tinalikuran ng isang matuwid na tao ang kaniyang pagkamatuwid at gagawa ng kasalanan, kung gayon mamamatay siya dahil dito!"},{"verse_number":19,"text":"At kapag ang masama ay tumalikod sa kaniyang mga kasamaan at gawin ang makatarungan at matuwid, mabubuhay siya dahil sa mga bagay na iyon!"},{"verse_number":20,"text":"Ngunit sinasabi ninyong mga tao, “Hindi patas ang kaparaanan ni Yahweh” Hahatulan ko ang bawat isa sa inyo ayon sa kaniyang kaparaanan, sambahayan ng Israel."},{"verse_number":21,"text":"Nangyari ito sa ikalabindalawang taon, sa ikalimang araw sa ikasampung buwan ng ating pagkabihag, isang pugante ang dumating sa akin mula sa Jerusalem at sinabi, “Nabihag na ang lungsod!”"},{"verse_number":22,"text":"Nasa akin na ang kamay ni Yahweh sa gabi bago dumating ang pugante, at nabuksan ang aking bibig sa pagkakataon na dumating siya sa akin ng madaling araw. Kaya nabuksan ang aking bibig at nakakapagsalita na ako/hindi na ako pipi!"},{"verse_number":23,"text":"At dumating ang salita ni Yahweh sa akin at sinabi,"},{"verse_number":24,"text":"“Anak ng tao, nagsasalita at nagsasabi ang mga naninirahan sa lugar ng pagkawasak sa lupain ng Israel ay nagsasalita at sinasabi, 'Nag-iisang tao lamang si Abraham, at minana niya ang lupain, ngunit marami tayo! Ang lupain ay ibinigay na sa atin bilang isang ari-arian.'"},{"verse_number":25,"text":"Kaya nga sabihin mo sa kanila, 'Ito ang sinasabi ng Panginoong Yahweh: Kumain kayo ng dugo at ibinaling ninyo ang inyong mga mata sa inyong mga diyus-diyosan at ibinuhos ninyo ang dugo ng mga tao. Dapat ba ninyong ariin ang lupain?"},{"verse_number":26,"text":"Nagtiwala kayo sa inyong mga espada at gumawa ng kasuklam-suklam na mga bagay. Dinudungisan ng bawat lalaki ang asawang babae ng kanilang kapwa. Dapat ba ninyong ariin ang lupain?'"},{"verse_number":27,"text":"Maaari mong sabihin ito sa kanila, 'Ito ang sinasabi ng Panginoong Yahweh: Habang buhay ako, siguradong ang mga nasa wasak na lungsod ay babagsak sa pamamagitan ng espada at ibibigay ko ang mga nasa parang sa mga nilalang na nabubuhay bilang pagkain at sa mga nasa tanggulan at mga kuweba ay mamamatay sa mga salot."},{"verse_number":28,"text":"At gagawin kong isang malagim at isang katakot-takot ang lupain at matatapos ang pagmamataas nito, At magiging napabayaan ang mga kabundukan ng Israel, at walang sinuman ang dadaan sa mga ito."},{"verse_number":29,"text":"Kaya malalaman nila na ako si Yahweh, kapag gagawin kong isang malagim ang lupain at katakot-takot dahil sa lahat ng mga kasuklam-suklam na mga bagay na kanilang ginawa."},{"verse_number":30,"text":"At ikaw, anak ng tao—nagsasabi ang iyong mga tao ng mga bagay tungkol sa iyo sa tabi ng mga pader at sa mga tarangkahan ng mga tahanan, at nagsasabi ang isa—sa bawat lalaki sa kapatid niyang lalaki, 'Pumaroon tayo at makinig sa salita ng propeta na mula kay Yahweh!'"},{"verse_number":31,"text":"Kaya pupunta ang aking mga tao sa iyo gaya ng madalas nilang ginagawa, at uupo sa iyong harapan at makikinig sa iyong mga salita, ngunit hindi nila ito susundin. Nasa kanilang mga bibig ang mga mabubuting salita ngunit sa kanilang mga puso, naghahangad sila ng hindi makatarungang pakinabang."},{"verse_number":32,"text":"Sapagkat ikaw ay parang isang kaibig-ibig na awitin sa kanila, isang magandang tunog na maayos na tinutugtog sa isang instrumentong may kuwerdas, kaya makikinig sila sa iyong mga salita ngunit wala sa kanila ang susunod nito."},{"verse_number":33,"text":"Kaya kapag mangyayari ang lahat ng ito—masdan! mangyayari ito! at malalaman nila na may isang propeta na kasama nila.”"}]},{"chapter_code":"EXO20","verses":[{"verse_number":1,"text":"Sinabi ng Diyos ang mga salitang ito:"},{"verse_number":2,"text":"“Ako ay si Yahweh, inyong Diyos, ang naglabas sa inyo mula sa lupain ng Ehipto, mula sa labas ng bahay ng pagkaalipin."},{"verse_number":3,"text":"Dapat wala kang ibang diyos sa harapan ko."},{"verse_number":4,"text":"Huwag dapat kayong gumawa para sa sarili ninyo ng isang inukit na larawan ni kahalintulad ng anumang bagay na nasa itaas ng langit, o sa lupa na nasa ilalim, o sa tubig na nasa ibaba."},{"verse_number":5,"text":"Huwag dapat kayong yuyukod sa kanila o sambahin sila, dahil Ako, si Yahweh na inyong Diyos, ay selosong Diyos. Paparusahan ko ang kasamaan ng mga ninuno sa pamamagitan ng pagpapadala ng kaparusahan sa mga kaapu-apuhan, patungo sa ikatlo at ikaapat na salinlahi sa mga galit sa akin."},{"verse_number":6,"text":"Pero magpapakita ako ng katapatan sa tipan sa libu-libong mga nagmamahal sa akin at susunod sa aking mga utos."},{"verse_number":7,"text":"Hindi ninyo dapat kunin ang pangalan ko, si Yahweh ang inyong Diyos, sa walang kabuluhan, dahil hindi ko ituturing na walang pagkakakasala ang sinumang kukuha ng pangalan ko sa walang kabuluhan."},{"verse_number":8,"text":"Alalahanin ninyo ang Araw ng Pamamahinga, ihandog ninyo ito sa akin."},{"verse_number":9,"text":"Dapat magtrabaho kayo at gawin ang lahat ng gawain sa loob ng anim na araw."},{"verse_number":10,"text":"Pero ang ikapitong araw, ay isang Araw ng Pamamahinga para sa akin, si Yahweh ang inyong Diyos. Dito dapat walang gagawa ng anumang gawain, ikaw, ni ang iyong anak na lalaki, ni ang iyong anak na babae, ni iyong lalaking lingkod, ni iyong babaeng lingkod, ni iyong baka, ni ang dayuhan na nasa loob ng iyong mga tarangkahan."},{"verse_number":11,"text":"Dahil sa ikaanim na araw Ako, si Yahweh, ang lumikha ng langit, lupa at dagat at lahat ng bagay na nasa loob nito at nagpahinga sa ikapitong araw. Kaya nga Ako, si Yahweh, ay pinagpala ang Araw ng Pamamahinga at inihandog ito sa aking sarili."},{"verse_number":12,"text":"Igalang ninyo ang inyong ama at inyong ina, para maaari kang manirahanng mahabang panahon sa lupain na ibibigay ko sa inyo Ako, si Yahweh, ang inyong Diyos."},{"verse_number":13,"text":"Hindi kayo dapat pumatay ng sinuman."},{"verse_number":14,"text":"Hindi kayo dapat mangalunya."},{"verse_number":15,"text":"Hindi kayo dapat magnakaw mula kaninuman."},{"verse_number":16,"text":"Hindi kayo dapat magbigay ng maling patotoo laban sa iyong kapwa."},{"verse_number":17,"text":"Hindi ninyo dapat kainggitan ang bahay ng iyong kapwa; hindi ninyo dapat kainggitan ang asawa ng iyong kapwa, ang kaniyang lingkod na lalaki, ang kaniyang lingkod na babae, ang kaniyang baka, kaniyang asno o anumang bagay na pag-aari ng kapwa mo.”"},{"verse_number":18,"text":"Nakita ng mga tao ang pagkulog at ang pagkidlat at narinig ang tunog ng trumpeta at nakitang umuusok ang bundok. Nang makita ito ng mga tao, nanginig sila at tumayo sa malayo."},{"verse_number":19,"text":"Sinabi nila kay Moises, “Makipag-usap ka sa amin at kami'y makikinig; pero huwag mong payagan makipag- usap sa amin ang Diyos, o lahat kami ay mamamatay.”"},{"verse_number":20,"text":"Sinabi ni Moises sa mga tao, “Huwag kayong matakot, dahil bumaba ang Diyos para kayo ay subukin para ang karangalan na nasa kaniya ay mapasainyo at para hindi kayo magkasala.”"},{"verse_number":21,"text":"Kaya ang mga tao ay tumayo sa malayo at lumapit si Moises tungo sa makapal na kadiliman kung saan naroon ang Diyos."},{"verse_number":22,"text":"Sinabi ni Yahweh kay Moises, “Ito ang sasabihin mo sa mga Israelita: 'Nakita mo na nakipag-usap ako sa iyo mula sa langit."},{"verse_number":23,"text":"Huwag kang gagawa para sa sarili mo ng anumang mga diyos kasama ko, mga diyos ng pilak o diyos ng ginto."},{"verse_number":24,"text":"Kailangan gumawa ka ng isang makalupang altar para sa akin at kailangang ihain mo itong mga handog na susunugin, mga handog ng pagtipon-tipon, tupa at mga baka. Sa bawat lugar na kung saan pararangalan ang pangalan ko, pupuntahan at pagpapalain kita."},{"verse_number":25,"text":"Kung igagawa mo ako ng isang altar mula sa bato, huwag mong itatayo mula sa hinati na mga bato, kapag ginamit mo ang iyong mga kasangkapan para dito, dinumihan mo ito."},{"verse_number":26,"text":"Huwag kang aakyat sa mga baitang patungo sa aking altar; ito ay hahadlang sa iyo mula sa paglantad ng pribadong bahagi ng iyong katawan.'”"}]},{"chapter_code":"JDG13","verses":[{"verse_number":1,"text":"Muling gumawa ng kasamaan sa paningin ni Yahweh ang bayan ng Israel, at pinahintulutan niya sila na pamunuan ng mga Palestina sa loob ng apatnapung taon."},{"verse_number":2,"text":"Mayroong isang lalaki na mula sa Zora, sa pamilya ng mga Danita, na ang pangalan ay Manoa. Walang kakayahang magbuntis ang kaniyang asawa kaya hindi siya magkaanak."},{"verse_number":3,"text":"Nagpakita ang anghel ni Yahweh sa babae at sinabi sa kaniya, “Tingnan mo ngayon, walang kang kakayahang magbuntis, at hindi ka magkaanak, pero mabubuntis ka at manganganak ng isang batang lalaki."},{"verse_number":4,"text":"Ngayon maging maingat, huwag uminom ng alak o matapang na inumin, at huwag kakain ng anumang maruming pagkain na inihayag ng batas na madumi."},{"verse_number":5,"text":"Masdan, mabubuntis ka at manganganak ng isang batang lalaki. Walang labaha ang gagamitin sa kaniyang ulo, sapagkat magiging Nazareo ang bata na inihandog para sa Diyos mula sa sinapupunan. Sisimulan niyang iligtas ang Israel mula sa kamay ng mga Palestina.”"},{"verse_number":6,"text":"Pagkatapos dumating ang babae at sinabi sa kaniyang asawa. “Nagpakita sa akin ang isang tao ng Diyos, at ang itsura ay katulad ng isang anghel ng Diyos, nagdulot siya sa akin ng labis na takot. Hindi ko tinanong kung saan siya galing, at hindi niya sinabi sa akin ang kaniyang pangalan."},{"verse_number":7,"text":"Sinabi niya sa akin, 'Masdan mo! Mabubuntis ka, at manganganak ng isang batang lalaki. Kaya hindi ka iinom ng alak o matapang na inumin, at huwag kakain ng anumang pagkain na hinayag ng batas na marumi, dahil magiging isang Nazareo sa Diyos ang bata mula sa araw na nasa sinapupunan mo siya hanggang sa araw ng kaniyang kamatayan.'”"},{"verse_number":8,"text":"Pagkatapos nanalangin si Manoa kay Yahweh at sinabi, “O, Panginoon, pakiusap hayaan na muling bumalik ang tao ng Diyos para matuuruan niya kami kung ano ang aming gagawin para sa bata na ipapanganak sa madaling panahon.”"},{"verse_number":9,"text":"Sumagot ang Diyos sa panalangin ni Manoa, at muling dumating sa babae ang anghel ng Diyos nang nakaupo siya sa bukid. Pero hindi niya kasama si Manoa na kaniyang asawa."},{"verse_number":10,"text":"Kaya agad na tumakbo ang babae at sinabi sa kaniyang asawa, “Tingnan mo! Ang tao na nagpakita sa akin—ang nagpunta sa akin noong isang araw!”"},{"verse_number":11,"text":"Tumayo si Manoa at sumunod sa kaniyang asawa. Nang lumapit siya sa tao, sinabi niya, “Ikaw ba iyong tao na naka-usap ng aking asawa?” Sinabi ng tao, “Ako nga.”"},{"verse_number":12,"text":"Kaya sinabi ni Manoa, “Ngayon nawa ang iyong salita ay magkatotoo. Pero ano ang alintuntun para sa bata, at ano ang kaniyang magiging tungkulin?”"},{"verse_number":13,"text":"Sinabi ng anghel ni Yahweh kay Manoa, dapat maingat niyang gawin ang lahat ng mga bagay na sinabi ko sa kaniya."},{"verse_number":14,"text":"Huwag siyang kakain ng anumang bagay na nagmumula sa puno ng ubas, at huwag hayaang uminom ng alak o matapang na inumin; huwag siyang hayaang kumain ng anumang pagkain na hinayag ng batas na marumi. Dapat niyang sundin ang lahat ng bagay na sinabi kong gawin niya."},{"verse_number":15,"text":"Sinabi ni Manoa sa anghel ni Yahweh, “Pakiusap manatili ka muna ng sandali, para bigyan kami ng panahon para maghanda ng isang batang kambing para sa iyo.”"},{"verse_number":16,"text":"Sinabi ng anghel ni Yahweh kay Manoa, “Kahit na manatili ako, hindi ko kakainin ang iyong pagkain. Pero kung maghahanda ka ng isang handog na susunugin, ihandog ito kay Yahweh.” (Hindi alam ni Manoa na siya ang anghel ni Yahweh.)"},{"verse_number":17,"text":"Sinabi ni Manoa sa anghel ni Yahweh, “Ano ang iyong pangalan, para maparangalan kita kapag nagkatotoo ang iyong mga salita?”"},{"verse_number":18,"text":"Sinabi ng anghel ni Yahweh sa kaniya, “Bakit mo tinatanong ang aking pangalan? Ito ay kahanga-hanga!”"},{"verse_number":19,"text":"Kaya kinuha ni Manoa ang batang kambing kasama ang handog na pagkaing butil at inihandog ang mga ito para kay Yahweh sa ibabaw ng bato. Gumawa siya ng isang bagay na kamangha-mangha habang nanunuod si Manoa at ang kaniyang asawa."},{"verse_number":20,"text":"Nang magliyab na ang apoy mula sa altar patungong langit, umakyat ang anghel ni Yahweh sa nagliliyab na apoy ng altar. Nakita ito ni Manoa at ng kaniyang asawa at nagpatirapa sila sa lupa."},{"verse_number":21,"text":"Hindi na muling nagpakita ang anghel ni Yahweh kay Manoa o sa kaniyang asawa. Pagkatapos malaman ni Manoa na siya ang anghel ni Yahweh."},{"verse_number":22,"text":"Sinabi ni Manoa sa kaniyang asawa, “Tiyak na mamamatay tayo, dahil nakita natin ang Diyos!”"},{"verse_number":23,"text":"Pero sinabi sa kaniya ng kaniyang asawa, “Kung nais tayong patayin ni Yahweh, hindi niya tatanggapin ang ating sinunog na handog at handog na pagkaing butil na ibinigay natin sa kaniya. Hindi niya ipapakita sa atin ang lahat ng mga bagay na ito, ni sa panahong ito na hayaan niya tayong marinig ang ganoong mga bagay.”"},{"verse_number":24,"text":"Dumating ang araw na nanganak ang babae sa isang batang lalaki, at tinawag siya sa pangalang Samson. Lumaki ang bata at pinagpala ni Yahweh."},{"verse_number":25,"text":"Nagsimulang kumilos sa kaniya ang Espiritu ni Yahweh sa Mahane Dan, sa pagitan ng Zora at Estaol."}]},{"chapter_code":"EZK18","verses":[{"verse_number":1,"text":"Ang salita ni Yahweh ay muling dumating sa akin at sinabi,"},{"verse_number":2,"text":"“Ano ang ibig mong sabihin, ikaw na gumamit ng kawikaang ito tungkol sa lupain ng Israel at nagsasabi, 'Ang mga ama na kumain ng mga maaasim na ubas, at ang ngipin ng mga anak ay nangilo?'"},{"verse_number":3,"text":"Habang Ako ay nabubuhay—ito ang pahayag ng Panginoong Yahweh—tiyak na hindi na magkakaroon pa ng anumang okasyon upang gamitin ninyo ang kawikaang ito sa Israel."},{"verse_number":4,"text":"Tingnan mo! Ang bawat buhay ay sa akin! At gayon din ang buhay ng ama at ang buhay ng anak sila ay sa akin! Ang taong nagkakasala ay mamamatay!"},{"verse_number":5,"text":"Sapagkat ang tao, kung siya ay matuwid at taglay ang katarungan at katuwiran—"},{"verse_number":6,"text":"kung hindi siya kumain sa mga dambana sa bundok, at hindi itinaas ang kaniyang mga mata sa mga diyus-diyosan ng sambahayan ng Israel— kung hindi niya dinungisan ang asawa ng kaniyang kapitbahay, o ni hindi lumapit sa isang babae sa panahong siya ay may regla—"},{"verse_number":7,"text":"kung wala siyang inaping sinuman sa halip ay nagsauli ng sangla sa umutang—kung hindi niya kinuha ang ninakaw, ngunit sa halip ay ibinibigay niya ang kaniyang pagkain sa mga nagugutom at tinatakpan ng mga damit ang hubad;"},{"verse_number":8,"text":"kung hindi siya nagpapatong ng anumang tubo sa pagpaputang, o kumuha ng labis na kita— kung isinasagawa niya ang katarungan at pinatitibay ang katapatan sa pagitan ng mga tao—"},{"verse_number":9,"text":"kung lumalakad siya sa aking mga kautusan at sinusunod ang aking mga alituntunin upang kumilos nang tapat—ang taong ito ay matuwid; siya ay mabubuhay! —ito ang pahayag ng Panginoong Yahweh."},{"verse_number":10,"text":"Subalit kung may anak siyang marahas na nagpapadanak ng dugo at ginagawa alinman sa mga bagay na ito—"},{"verse_number":11,"text":"kahit na hindi ginagawa ng kaniyang ama ang alinman sa mga bagay na ito— subalit kung ang kaniyang anak na lalaki ay kumain sa mga dambana sa bundok at sipingan ang asawa ng kapitbahay—"},{"verse_number":12,"text":"kung inaapi niya ang mahirap at nangangailangan, kung sumasamsam siya at nagnanakaw at hindi ibinabalik ang sangla, kung itinataas niya ang kaniyang mga mata sa mga diyos-diyusan o gumagawa ng mga kasuklam-suklam na gawain;"},{"verse_number":13,"text":"at kung nagpapautang siya na nagpapabayad ng tubo at kumukuha ng hindi makatarungang kita, dapat ba siyang mabuhay? Siya ay hindi mabubuhay! Ginawa niya ang lahat ng kasuklam-suklam na ito. Siya ay tiyak na mamamatay; ang kaniyang dugo ay nasa kaniya."},{"verse_number":14,"text":"Subalit tingnan mo! Kung magkaanak siya ng isang lalaking nakikita ang lahat ng kasalanang ginawa ng kaniyang ama, at kung siya mismo ay may takot sa Diyos at hindi ginagawa ang mga ganoong bagay—"},{"verse_number":15,"text":"at kung hindi siya kumain sa mga dambana sa bundok o itinaas ang kaniyang mga mata sa mga diyus-diyosan ng sambahayan ng Israel—kung hindi niya sumiping sa asawa ng kaniyang kapitbahay;"},{"verse_number":16,"text":"Kung hindi niya inaapi ang sinuman, sinasamsam ang sangla, o kinukuha ang mga nakaw na bagay, ngunit sa halip ibinibigay ang kaniyang pagkain sa nagugutom at tinatakpan ng mga damit ang hubad—"},{"verse_number":17,"text":"kung iniurong niya ang kaniyang kamay sa paghatol sa mahirap at hindi kumukuha ng tubo o hindi makatarungang kita; kung sinusunod niya ang aking mga alituntunin at lumalakad ayon sa aking mga kautusan, hindi siya mamamatay para sa kasalanan ng kaniyang ama. Siya ay tiyak na mabubuhay!"},{"verse_number":18,"text":"Ang kaniyang ama, sapagkat inapi niya ang iba sa pamamagitan ng pagkuha nang sapilitan at ninakawan ang kaniyang kapatid na lalaki, at ginawa ang hindi mabuti sa mga tao—tingnan mo, siya ay mamamatay sa kaniyang malaking kasalanan."},{"verse_number":19,"text":"Subalit sinasabi mo, 'Bakit hindi magawang akuin ng anak ang katampalasan ng kaniyang ama?' Dahil isinasagawa ng lalaking anak ang katarungan at katuwiran; at iniingatan ang aking mga utos at ginagawa niya ang mga ito. Tiyak na mabubuhay siya!"},{"verse_number":20,"text":"Ang siyang nagkasala, siya ang mamamatay. Hindi dadalhin ng anak ang kasalanan ng kaniyang ama, at hindi dadalhin ng ama ang kasalanan ng kaniyang anak. Ang katuwiran ng taong kumikilos nang makatarungan ay sa kaniyang sarili, at ang kasamaan ng masamang tao ay sa kaniyang sarili."},{"verse_number":21,"text":"Ngunit kung ang taong makasalanan ay tatalikod sa lahat ng kaniyang mga ginawang kasalanan, at iingatan ang aking mga kautusan at isasagawa ang katarungan at katuwiran, tiyak na mabubuhay siya at hindi mamamatay."},{"verse_number":22,"text":"Lahat ng pagsuway na kaniyang ginawa ay hindi na aalalahanin laban sa kanila. Siya ay mabubuhay sa pamamagitan ng katuwiran na kaniyang ginagawa na patuloy na ginagawa."},{"verse_number":23,"text":"Labis ko bang ikinagagalak ang pagkamatay ng makasalanan—ito ang pahayag ng Panginoong Yahweh—at hindi ang kaniyang pagtalikod mula sa kaniyang kaparaanan upang siya ay mabuhay?"},{"verse_number":24,"text":"Subalit kung ang matuwid na tao ay tumalikod sa kaniyang pagkamakatuwiran at isinagawa ang mga kasuklam-suklam tulad ng lahat ng kasuklam-suklam na ginagawa ng masamang tao, mabubuhay ba siya? Lahat ng matuwid na kaniyang ginawa ay hindi aalalahanin kapag ipinagkanulo niya ako sa kaniyang kataksilan. Kaya siya ay mamamatay sa mga kasalanang kaniyang ginawa."},{"verse_number":25,"text":"Subalit sinabi mo, 'Ang pamamaraan ng Panginoon ay hindi makatarungan! Makinig ka sambahayan ng Israel! Ang pamamaraan ko ba ay hindi makatarungan?"},{"verse_number":26,"text":"Kung ang matuwid na tao ay tumalikod sa kaniyang pagkamakatuwiran, at gumawa ng kasalanan at mamatay dahil sa mga ito, mamamatay siya sa kasalanang ginawa niya."},{"verse_number":27,"text":"Ngunit kapag ang masamang tao ay tumalikod sa kasamaang ginawa niya at gumawa ng katarungan at katuwiran, kung gayon pinangangalagaan niya ang kaniyang buhay!"},{"verse_number":28,"text":"Sapagkat nakita niya at tumalikod mula sa lahat ng mga kasalanang ginawa niya. Siya ay mabubuhay; hindi siya mamamatay!"},{"verse_number":29,"text":"Sinabi ng sambahayang Israel, 'Ang kaparaanan ng Panginoon ay hindi makatarungan! Paanong ang aking kaparaanan ay hindi makatarungan, sambahayan ng Israel? At paanong ang iyong pamamaraan ay makatarungan?"},{"verse_number":30,"text":"Kaya hahatulan ko ang bawat isa sa inyo ayon sa inyong kaparaanan, sambahayan ng Israel! —ito ang pahayag ng Panginoong Yahweh. Magsisi kayo at talikuran ninyo ang lahat ng inyong mga pagsalangsang upang ang mga ito ay hindi maging kasalanan na katitisuran laban sa inyo."},{"verse_number":31,"text":"Itapon palayo mula sa inyong sarili ang lahat ng mga pagsuway na inyong ginawa; magkaroon kayo ng bagong puso at bagong espiritu para sa inyong sarili. Sapagkat bakit kayo mamamatay, sambahayan ng Israel?"},{"verse_number":32,"text":"Sapagkat hindi ako nagagalak sa pagkamatay ng isang namatay—ito ang pahayag ng Panginoong Yahweh- kaya magsisi at mabuhay!”"}]},{"chapter_code":"1JN02","verses":[{"verse_number":1,"text":"Mga minamahal kong anak, isinusulat ko ang mga bagay na ito sa inyo upang hindi kayo magkasala. Pero kung sino man ang magkasala, mayroon tayong tagapagtanggol sa Ama, Si Jesu-Cristo ang nag-iisang makatuwiran."},{"verse_number":2,"text":"Siya ang taga-pamayapa para sa ating mga kasalanan, at hindi lang para sa atin, kundi para din sa buong mundo."},{"verse_number":3,"text":"Sa pamamagitan nito alam nating kilala natin siya, kung iniingatan natin ang kanyang mga kautusan."},{"verse_number":4,"text":"Siya na nagsasabing, “Kilala ko ang Diyos,” pero hindi pinapanatili ang kanyang mga kautusan, ay isang sinungaling, at ang katotohanan ay wala sa kanya."},{"verse_number":5,"text":"Pero ang sinumang pinapanatili ang kaniyang salita, tunay na sa taong ito ang pag-ibig ng Diyos ay naging lubos. Sa pamamagitan nito alam nating tayo ay nasa kaniya."},{"verse_number":6,"text":"Siya na nagsasabing siya ay nananatili sa Diyos ay nararapat ding lumakad nang katulad ng paglakad ni Jesu-Cristo."},{"verse_number":7,"text":"Mga minamahal, hindi ako nagsusulat nang bagong kautusan sa inyo, pero isang lumang kautusan na nasa sa inyo mula pa sa simula. Ang lumang kautusan ay ang salitang inyong narinig."},{"verse_number":8,"text":"Gayon pa man ako ay sumusulat ng bagong kautusan sa inyo, na siyang totoo kay Cristo at sa inyo, dahil ang kadiliman ay lumilipas na, at ang tunay na liwanag ay sumisinag na."},{"verse_number":9,"text":"Ang nagsasabing siya ay nasa liwanag pero kinapopootan ang kanyang kapatid ay nasa kadiliman kahit ngayon."},{"verse_number":10,"text":"Ang sinumang nagmamahal sa kanyang kapatid ay nananatili sa liwanag at walang pagkakataon na siya ay matitisod."},{"verse_number":11,"text":"Pero ang siyang napopoot sa kanyang kapatid ay nasa kadiliman at lumalakad sa kadiliman; hindi niya alam kung saan siya papunta, dahil binulag ng kadiliman ang kanyang mga mata."},{"verse_number":12,"text":"Sumusulat ako sa inyo, mga minamahal kong anak, dahil ang inyong mga kasalanan ay napatawad dahil sa kanyang pangalan."},{"verse_number":13,"text":"Sumusulat ako sa inyo mga ama, dahil kilala ninyo siya na mula pa sa simula. Sumusulat ako sa inyo mga kabataang lalaki, dahil napagtagumpayan ninyo ang kasamaan. Sumulat ako sa inyo, mga bata, dahil kilala ninyo ang Ama."},{"verse_number":14,"text":"Sumulat ako sa inyo mga ama, dahil kilala ninyo siya na mula pa sa simula. Sumulat ako sa inyo mga kabataang lalaki, dahil kayo ay malakas, at ang salita ng Diyos ay nananatili sa inyo, at napagtagumpayan ninyo ang kasamaan."},{"verse_number":15,"text":"Huwag ninyong mahalin ang mundo ni anumang mga bagay na nasa mundo. Kung sinumang umiibig sa mundo, ang pag-ibig ng Ama ay wala sa kanya."},{"verse_number":16,"text":"Pagkat ang lahat ng nasa sa mundo - ang kahalayan ng laman, ang kahalayan ng mata, at ang kahambugan sa buhay - ay hindi sa Ama pero sa mundo."},{"verse_number":17,"text":"Ang mundo at ang pagnanasa nito ay lumilipas. Pero ang sinumang gumagawa ng kalooban ng Diyos ay mananatili magpakailanman."},{"verse_number":18,"text":"Mga bata, ito na ang huling oras. Gaya nang narinig ninyo na ang antikristo ay darating, kahit ngayon ay may marami nang mga antikristong dumating, sa pamamagitan nito nalalaman nating ito na ang huling oras."},{"verse_number":19,"text":"Sila ay lumabas mula sa atin, pero hindi sila sa atin. Pagkat kung sila ay naging sa atin, sana ay nagpatuloy silang kasama natin. Pero nang sila ay lumabas, iyon ang nagpakitang sila ay hindi sa atin."},{"verse_number":20,"text":"Pero kayo ay may basbas mula sa Kabanal-banalan, at alam ninyong lahat ang katotohanan."},{"verse_number":21,"text":"Hindi ako sumulat sa inyo dahil sa hindi ninyo alam ang katotohanan, pero dahil sa alam ninyo ito at dahil walang kasinungalingan ang nasa katotohanan."},{"verse_number":22,"text":"Sino ang sinungaling kundi siyang ikinakaila na si Jesus ay ang Cristo? Ang taong ito ang antikristo, dahil sa kinakaila niya ang Ama at ang Anak."},{"verse_number":23,"text":"Walang sinuman ang kumakaila sa Anak ay nasa kaniya ang Ama. Ang sinumang kumikilala sa Anak ay nasa kaniya rin ang Ama."},{"verse_number":24,"text":"At para sa inyo, hayaang ang mga narinig ninyo mula sa simula ay manatili sa inyo. Kung ano ang narinig ninyo mula sa simula ay nanatili sa inyo, kayo rin ay mananatili sa Anak at sa Ama."},{"verse_number":25,"text":"At ito ang pangakong ibinigay niya sa atin: buhay na walang hanggan."},{"verse_number":26,"text":"Isinulat ko sa inyo ang mga ito tungkol sa mga iyon na maaaring umakay sa inyo sa ligaw na landas."},{"verse_number":27,"text":"At para sa inyo, ang basbas na natanggap ninyo mula sa kanya ay nanatili sa inyo, at hindi ninyo kailangan ang sinuman upang turuan kayo. Pero habang ang kanyang pagbabasbas ay nagtuturo sa inyo ng tungkol sa lahat ng bagay, at totoo at hindi isang kasinungalingan, at kahit na ito ay nagturo sa inyo, manatili kayo sa kanya."},{"verse_number":28,"text":"At ngayon, mga minamahal kong anak, manatili kayo sa kanya, upang kapag siya ay magpakita, tayo ay magkakaroon nang lakas ng loob at hindi mahihiya sa kanyang harapan sa kanyang pagdating."},{"verse_number":29,"text":"Kung alam ninyo na siya ay makatuwiran, alam ninyong ang lahat nang gumagawa ng tama ay ipinanganak sa kanya."}]},{"chapter_code":"PSA100","verses":[{"verse_number":1,"text":"Sumigaw na may kagalakan kay Yahweh, buong daigdig."},{"verse_number":2,"text":"Maglingkod kay Yahweh ng may kasiyahan; magsilapit sa kanyang presensiya na umaawit nang may kagalakan."},{"verse_number":3,"text":"Kilalalanin ninyo na si Yahweh ay Diyos; siya ang gumawa sa atin, at tayo ay sa kanya. Tayo ang kanyang bayan at mga tupa sa kanyang pastulan."},{"verse_number":4,"text":"Magsipasok kayo sa loob ng kanyang mga tarangkahan na may pagpapasalamat at sa loob ng kanyang mga silid na may pagpupuri. Pasalamatan at purihin ang kanyang pangalan."},{"verse_number":5,"text":"Dahil si Yahweh ay mabuti; ang kanyang katapatan sa tipan ay mananatili magpakailanman at ang kanyang pagiging totoo ay magpapatuloy sa lahat ng mga salinlahi."}]},{"chapter_code":"PSA023","verses":[{"verse_number":1,"text":"Si Yahweh ang aking pastol; hindi ako magkukulang."},{"verse_number":2,"text":"Pinahihiga niya ako sa luntiang mga pastulan; inaakay niya ako sa tabi ng payapang tubigan."},{"verse_number":3,"text":"Binabalik niya ang aking buhay; ginagabayan niya ako sa tamang landas alang-alang sa kaniyang pangalan."},{"verse_number":4,"text":"Kahit na lumakad ako sa gitna ng napakadilim na anino ng lambak, hindi ko katatakutan ang kapahamakan dahil ikaw ang kasama ko; ang iyong pamalo at iyong tungkod ang nagpapayapa sa akin."},{"verse_number":5,"text":"Ipinaghahanda mo ako ng isang hapag sa harapan ng aking mga kaaway; binuhusan mo ng langis ang aking ulo; ang saro ko ay nag-uumapaw."},{"verse_number":6,"text":"Tiyak na kabutihan at katapatan sa tipan ang hahabol sa akin sa lahat ng mga araw ng aking buhay; at ako ay mananahanan sa tahanan ni Yahweh habang buhay!"}]},{"chapter_code":"2JN01","verses":[{"verse_number":1,"text":"Mula sa nakatatanda hanggang sa piniling babae at sa kanyang mga anak, na siyang minamahal ko sa katotohanan, at hindi lamang ako, kundi lahat din ng mga sinumang nakakaalam ng katotohanan,"},{"verse_number":2,"text":"dahil sa katotohanan na nananatili sa atin at mapapasaatin magpakailanman."},{"verse_number":3,"text":"Biyaya, habag, at kapayapaan ay mapapasaatin mula sa Diyos na Ama at mula kay Jesu-Cristo, ang Anak ng Ama, sa katotohanan at pag-ibig."},{"verse_number":4,"text":"Ako ay lubos na nagagalak na nakita ko ang iba mong mga anak na lumalakad sa katotohanan, tulad ng aming pagtanggap sa kautusang ito galing sa Ama."},{"verse_number":5,"text":"At ngayon ako ay nagsusumamo sa iyo, ginang, hindi na parang ako ay sumulat sa iyo ng bagong kautusan, pero ang mayroon na tayo mula pa sa simula, na dapat nating ibigin ang bawat isa."},{"verse_number":6,"text":"At ito ang pag-ibig, na dapat tayong lumakad ayon sa kanyang mga kautusan. Ito ang kautusan, kahit narinig ninyo na mula sa simula, na dapat ninyo itong lakaran."},{"verse_number":7,"text":"Sapagkat maraming manlilinlang ang naglipana sa mundo, at hindi nila ipinapahayag na si Jesu-Cristo ay dumating sa laman. Ito ay ang manlilinlang at ang anticristo."},{"verse_number":8,"text":"Tingnan ang inyong mga sarili, upang hindi ninyo mawala ang mga bagay na pinagtrabahuhan nating lahat, pero nang sa gayon kayo ay maaaring makatanggap ng buong gantimpala."},{"verse_number":9,"text":"Kung sinuman ang nauuna at hindi nananatili sa katuruan ni Cristo ay walang Diyos. Siya na nananatili sa katuruan ay nasa kanya pareho ang Ama at ang Anak."},{"verse_number":10,"text":"Kung sinuman ang lumapit sa inyo at hindi dala ang katuruang ito, huwag ninyo siyang tanggapin sa inyong bahay at huwag ninyo siyang batiin."},{"verse_number":11,"text":"Sapagkat ang sinumang bumabati sa kaniya ay nakikisali sa kaniyang mga masasamang gawa."},{"verse_number":12,"text":"Marami akong mga bagay na isusulat sa inyo at hindi ko nais na isulat ang mga ito sa pamamagitan ng papel at tinta. Pero umaasa akong pumunta sa inyo at makipag-usap ng harap-harapan, upang ang ating kaligayahan ay maging lubos."},{"verse_number":13,"text":"Ang mga anak nang pinili ninyong kapatid na babae ay bumabati sa inyo."}]},{"chapter_code":"3JN01","verses":[{"verse_number":1,"text":"Ang nakatatanda para kay minamahal na si Gayo, na siyang aking mahal sa katotohanan."},{"verse_number":2,"text":"Minamahal, dinadalangin ko na ikaw ay lumago sa lahat ng mga bagay at maging sa kalusugan, katulad ng paglago ng iyong kaluluwa."},{"verse_number":3,"text":"Sapagkat ako ay lubos na nagalak nang dumating ang mga kapatid na lalaki at nagpatotoo sa iyong katotohanan, katulad sa paglakad mo sa katotohanan."},{"verse_number":4,"text":"Wala akong labis na kaligayahan maliban dito, na marinig na ang aking mga anak ay lumalakad sa katotohanan."},{"verse_number":5,"text":"Minamahal, ikaw ay nagsasagawa ng katapatan tuwing ikaw ay gumagawa para sa iyong mga kapatid na lalaki at para sa mga hindi kilala,"},{"verse_number":6,"text":"siya na nagpatotoo ng pag-ibig mo sa harapan ng iglesia. Gumawa ka ng mainam para maipadala sila sa kanilang paglalakbay sa paraang karapat-dapat sa Diyos,"},{"verse_number":7,"text":"dahil para sa kapakanan ng Pangalan sila ay lumabas, walang kinukuha mula sa mga Gentil."},{"verse_number":8,"text":"Samakatuwid tayo ay marapat na tumanggap tulad ng mga ito, nang sa gayon tayo ay maging kapwa manggagawa para sa katotohanan."},{"verse_number":9,"text":"Nagsulat ako ng isang bagay sa kapulungan, pero si Diotrefes, na gustong maging una sa kanila, ay hindi tayo tinanggap."},{"verse_number":10,"text":"Samakatuwid, kung ako ay pupunta, aalalahanin ko ang mga gawaing kaniyang ginawa, kung paano siyang nagsabi ng mga katawa-tawang bagay laban sa atin gamit ang mga masasamang salita. Hindi pa nasiyahan sa mga gawaing ito, siya mismo ay hindi tinanggap ang mga kapatid na lalaki. Ipinagbabawal niya ang mga nagnanais na gumawa nito at pinapalayas sila sa kapulungan."},{"verse_number":11,"text":"Minamahal, huwag mong tularan kung ano ang masama pero kung ano ang mabuti. Ang siyang gumagawa ng mabuti ay sa Diyos; ang siyang gumagawa ng masama ay hindi nakita ang Diyos."},{"verse_number":12,"text":"Si Demetrio ay nagpatotoo sa lahat at sa pamamagitan ng katotohanan mismo. Tayo din ay nagpapatotoo, at alam mo na ang aming pagpapatotoo ay tunay."},{"verse_number":13,"text":"Marami akong bagay na isusulat sa iyo, pero hindi ko nais isulat ang mga ito sa iyo na gamit ang panulat at tinta."},{"verse_number":14,"text":"Pero ako ay umaasa na makita ka sa lalong madaling panahon, at tayo ay mag-uusap harap-harapan."},{"verse_number":15,"text":"Kapayapaan ay sumainyo. Ang mga kaibigan ay bumabati sa iyo. Batiin ang mga kaibigan sa pangalan."}]},{"chapter_code":"JUD01","verses":[{"verse_number":1,"text":"Judas, isang lingkod ni Jesu-Cristo, at kapatid na lalaki ni Santiago, sa kanilang mga tinawag, minamahal sa Diyos Ama at nanatili para kay Jesu-Cristo,"},{"verse_number":2,"text":"nawa ang awa, kapayapaan at pag-ibig ay sumagana sa inyo."},{"verse_number":3,"text":"Minamahal, habang sinisikap kong sumulat sa inyo tungkol sa ating pangkalahatang kaligtasan, kailangang sulatan ko kayo upang hikayatin kayo na magsumikap para sa pananampalataya na minsan nang ibinigay sa lahat ng mga naniniwala."},{"verse_number":4,"text":"Dahil may ibang mga tao na palihim na nakisama sa kalagitnaan ninyo—mga taong tinatakan ng paghahatol - mga taong walang Diyos na inililihis ang biyaya ng Panginoon patungo sa kahalayan at itinatanggi ang ating nag-iisang Panginoon at Diyos na si Jesu- Cristo."},{"verse_number":5,"text":"Ngayon nais kong ipaalala sa inyo, kahit na lubos na ninyong alam ito, na ang Panginoon ang nagligtas sa isang bayan palabas sa lupain ng Ehipto, ngunit pagkatapos pinuksa niya ang mga hindi naniwala."},{"verse_number":6,"text":"At ang mga anghel na hindi nanatili sa kani-kanilang makapangyarihang tungkulin- ngunit iniwan ang kanilang nararapat na lugar- ginapos sila ng Diyos sa walang hanggang mga tanikala, sa lubos na kadiliman, para sa dakilang araw ng paghuhukom."},{"verse_number":7,"text":"Katulad ito ng Sodom at Gomorra at ang mga lungsod sa paligid nila, na nagpasasa din sa sekswal na imoralidad at sila ay nagpatuloy sa hindi likas na pagnanasa. Sila ay ipinakita bilang mga halimbawa ng mga nagdurusa sa parusa ng walang hanggang apoy."},{"verse_number":8,"text":"Gayunman sa parehong paraan, ang mga nananaginip na ito ay dinudungisan din ang kanilang mga katawan, at tinatanggihan ang awtoridad, at sinisiraan nila ang dangal ng mga maluwalhating mga anghel."},{"verse_number":9,"text":"Subalit maging si Miguel ang arkanghel, nang siya ay nakipagtalo sa diyablo at nakipaglaban sa kaniya tungkol sa katawan ni Moises, ay hindi nangahas magbigay ng mapanirang paghatol laban sa kaniya, sa halip sinabi niya, “Sawayin ka nawa ng Diyos!”"},{"verse_number":10,"text":"Ngunit nagbibigay ng mga paninirang-puri ang mga taong ito laban sa anumang hindi nila maintindihan. At ano kanilang naiintindihan— kung ano ang pag-uugali ng mga hayop na wala sa katuwiran— ang mga ito ang nagpahamak sa kanila."},{"verse_number":11,"text":"Kaawa-awa sila! Dahil sila ay lumakad sa daan ni Cain, at nahulog sa pagkakamali ni Balaam. Sila ay namatay sa paghihimagsik ni Kora."},{"verse_number":12,"text":"Ang mga ito ang siyang tinik sa inyong mga pista ng pag-ibig, nagpipista na walang kahihiyan, kumakain lamang para sa kanilang mga sarili. Sila ay mga ulap na walang tubig, tinatangay ng hangin, puno sa taglagas na walang bunga- dalawang beses namatay, binunot sa ugat-"},{"verse_number":13,"text":"marahas na mga alon ng dagat, na bumubulang palabas sa kanilang sariling kahihiyan, gumagala na mga tala—na sa kaitiman ng kadiliman ay nakalaan ang magpakailanman."},{"verse_number":14,"text":"Si Enoc, ang ika-pito sa linya mula kay Adan, nagpahayag tungkol sa kanila, na sinasabing, “Pagmasdan ninyo! Ang Panginoon ay darating kasama ang libo-libong mga banal,"},{"verse_number":15,"text":"upang magsagawa ng paghuhukom sa bawat isa, at hatulan ang lahat ng hindi maka-diyos sa kanilang mga ginagawa at pamamaraan, at sa lahat ng mga magaspang na pananalita na binigkas ng mga makasalanan laban sa Diyos."},{"verse_number":16,"text":"Ito ay ang mga bumubulong-bulong, mga mareklamo, silang mga sumusunod sa kanilang masasamang pagnanasa, maingay na mga hambog, at sila na nang-uuto para sa sariling kapakinabangan."},{"verse_number":17,"text":"Pero kayo, mga minamahal, alalahanin ang mga salitang sinabi sa inyo noon ng mga apostol ng Panginoong Jesu-Cristo."},{"verse_number":18,"text":"Sinabi nila sa inyo, “ Sa huling panahon, may mga mangungutya na sinusunod ang kanilang sariling hindi maka-diyos na pagnanasa.”"},{"verse_number":19,"text":"Ang mga taong ito ay dahilan ng pagkaba-bahagi, pinamumunuan ng makamundong pagnanasa, at wala sa kanila ang Espiritu."},{"verse_number":20,"text":"Pero kayo, mga minamahal, habang tinataguyod ninyo ang inyong mga sarili sa inyong kabanal-banalang pananampalataya, at habang nananalangin kayo sa Banal na Espiritu,"},{"verse_number":21,"text":"panatilihin ang inyong sarili sa pag-ibig ng Diyos at hintayin ang awa ng ating Panginoong Jesu-Cristo na nagdadala sa inyo ng buhay na walang hanggan."},{"verse_number":22,"text":"Magpakita ng habag sa mga nag-aalinlangan."},{"verse_number":23,"text":"Iligtas ang iba sa pamamagitan ng pag-agaw sa kanila mula sa apoy. Sa iba magpakita ng habag na may takot, kamumuhian kahit na ang damit na nabahiran ng laman."},{"verse_number":24,"text":"Ngayon sa kanya na may kakayanang ilayo kayo sa pagkakatisod, at dahilan upang tayo ay makatayo sa harapan ng kanyang maluwalhating presensya, walang dungis at may labis na kagalakan,"},{"verse_number":25,"text":"sa tanging Diyos ating tagapagligtas sa pamamagitan ni Jesu-Cristo ating Panginoon, ang kaluwalhatian, kadakilaan, kataas-taasan, kapangyarihan-bago sa lahat ng panahon, at ngayon, at magpakailanman. Amen."}]}];
  return chapters;
}
